            def url(page):
                parts = ["%s=%s" % kv for kv in params.items() if kv[0] != "page"] + ["page=%d" % page]
                return "<https://api.github.com/repositories/%d/%s?%s>" % (REPO_NUMERIC_ID, rel, "&".join(parts))
            link = '%s; rel="next", %s; rel="last"' % (url(n + 1), url(last))
