class StampFailure(Env):
    """stamp.mjs fails for any reason: merge prints one line with the reason and a remedy, never a stack trace."""
    def stamp_fails(self, program, reason):
        before = self.head()
        with unittest.mock.patch.object(merge, "STAMP", program):
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        stamp_lines = [l for l in out.splitlines() if "claim was refused" in l]  # the stamp line alone
        self.assertEqual(len(stamp_lines), 1, out)
        self.assertIn(reason, stamp_lines[0])
        self.assertNotIn("    at ", out)
        self.assertNotIn("Traceback", out)
        self.assertEqual(self.head(), before)  # nothing was pushed

    def test_a_stamp_that_throws_prints_one_line_and_no_stack(self):
        program = os.path.join(self.t, "throws.mjs")
        put(program, 'throw new Error("boom: fake stamp failure");\n')
        self.stamp_fails(program, "boom")

    def test_a_missing_stamp_program_prints_one_line_and_no_stack(self):
        self.stamp_fails(os.path.join(self.t, "no-such-stamp.mjs"), "Cannot find module")

class SilentUndo(Env):
    def stale_feat(self):
        """main gains lines in first.md, then feat merges main keeping ours: feat carries the old file."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
        put(os.path.join(o, "docs/decisions/first.md"), record("D-001", "first") + "newer line a\nnewer line b\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "main moves"); sh(o, "git", "push", "-q", "origin", "main")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(o, "git", "merge", "-q", "-s", "ours", "--no-edit", "origin/main")
        sh(o, "git", "push", "-q", "origin", "feat")

    def test_a_stale_branch_is_refused_before_anything_is_pushed(self):
        self.stale_feat()
        before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("silently undoes", out)
        self.assertIn("first.md", out)
        self.assertEqual(self.refs(), before)
        self.assertEqual(self.host.waits, [])
        self.assertFalse(self.lock_ref())  # a refusal frees the lock

    def test_a_trailer_lets_the_deliberate_drop_merge(self):
        self.stale_feat()
        o = self.other
        sh(o, "git", "commit", "-q", "--allow-empty", "-m", "Drop them on purpose\n\nDrops-lines: docs/decisions/first.md -- the lines are dead")
        sh(o, "git", "push", "-q", "origin", "feat")
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)

    def test_the_check_runs_again_after_the_wait_and_a_red_reverts_the_claim(self):
        calls = []
        real = merge.undo_check
        def second_is_red(wt, base, unknown_ok="", pr_body="", run_state=None, retire_head=None):
            calls.append(base)
            if len(calls) == 2:
                raise merge.Stop("the branch silently undoes earlier work: main moved during the wait")
            return real(wt, base, unknown_ok, pr_body, run_state, retire_head)
        with unittest.mock.patch.object(merge, "undo_check", second_is_red):
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(len(calls), 2)
        self.assertEqual(rc, 1)
        self.assertEqual(self.claims(), 0)
        self.assertFalse(getattr(self.host, "merged", False))

    def test_the_silent_undo_check_gets_the_cite_reader_and_the_pr_head_at_each_read(self):
        """undo.check is handed run_state (a reader of a cited run, through the host) and retire_head (the PR head, as read at
        the start). The claim at confirm moves the branch, so a read after it has a worktree HEAD that is not the PR head."""
        DebtRetire.pr_on_debt(self, 0)
        pr_head = self.head()
        reads = []
        self.host.cited_run = lambda url: (reads.append(url), ("success", pr_head))[1]
        sys.path.insert(0, os.path.join(HERE, "..", "lint"))
        import check_silent_undo as undo
        seen = []

        def spy(*a, **k):
            seen.append(k)
            return [], []
        with unittest.mock.patch.object(undo, "check", spy):
            rc_preview, out_preview = self.run_merge("7")
            rc, out = self.run_merge("7", "--confirm")
        self.assertGreaterEqual(len(seen), 2, out_preview + out)
        for k in seen:
            self.assertIn("run_state", k, "undo.check got no run_state: a Retire-run cite cannot reach the silent-undo check")
            self.assertEqual(k.get("retire_head"), pr_head, "undo.check got a retire_head that is not the PR head")
            k["run_state"]("https://github.com/fixture/repo/actions/runs/42")
        self.assertTrue(reads, "the run reader undo.check got does not reach the host's cited_run")
        self.assertEqual((rc_preview, rc), (0, 0), out_preview + out)


DEBT_FIXTURE = "# Retire target\n\n- **What.** A fixture debt for the merge tests.\n- **Where.** None.\n- **Decision.** none\n- **Retire.** %s\n"
RETIRE_TEST = "Delete the fixture. Check: `tests/test_retire_target.py`."


def names_kind(test, out, slug, kind):
    """The printed line that names debt `slug` must also name its kind."""
    line = printed(out, slug)
    test.assertTrue(line, "no printed line names debt %s: %s" % (slug, out))
    test.assertIn(kind, line, "the line for debt %s does not name its kind %s: %s" % (slug, kind, line))


def unextended_checks(events, kind, bound):
    """-> the positions in `events` of each check call of `kind` that no lock extension of at least `bound` seconds came before, since the check
    call before it. `events` holds ("extend", wait) for each extend_for call and ("check", kind) for each check call, in the order the run made them."""
    longest, found = 0, []
    for pos, (what, arg) in enumerate(events):
        if what == "extend":
            longest = max(longest, arg)
            continue
        if arg == kind and longest < bound:
            found.append(pos)
        longest = 0  # each check call needs its own extension before it
    return found


class NoExtendLock(merge.GitLock):
    """A GitLock with no extend_for attribute: getattr(lock, "extend_for", None) reads None, and a direct call raises."""
    @property
    def extend_for(self):
        raise AttributeError("this lock has no extend_for")


class DebtRetire(Env):
    """A PR that closes a debt (deletes the debt file) runs that debt's Retire check on the PR head before preview or confirm
    lets it through. The fixture debt names tests/test_retire_target.py, which exits with the code each case gives it."""

    def pr_on_debt(self, test_exit, closes=True, retire=RETIRE_TEST, test_text=None):
        """main gains a debt file. feat is cut from that main, adds the pending record and the test, and then either deletes
        the debt (closes) or edits it in place. feat is cut from main after the debt lands, so no main commit is a reversal of it."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
        put(os.path.join(o, ".claude/layout-extras.json"), json.dumps({"kinds": {}, "rolled-out": True}))
        put(os.path.join(o, "docs/debts/retire-target.md"), DEBT_FIXTURE % retire)
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "main: a debt"); sh(o, "git", "push", "-q", "origin", "main")
        put(os.path.join(o, "main-moves.txt"), "main moves on\n")  # feat is cut from a later main, so the debt commit is not one it left
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "main: moves on"); sh(o, "git", "push", "-q", "origin", "main")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/main")
        put(os.path.join(o, "docs/decisions/second.md"), record("pending", "second"))
        put(os.path.join(o, "tests/test_retire_target.py"), test_text or "import sys\nsys.exit(%d)\n" % test_exit)
        if closes:
            sh(o, "git", "rm", "-q", "docs/debts/retire-target.md")
        else:
            put(os.path.join(o, "docs/debts/retire-target.md"), DEBT_FIXTURE % RETIRE_TEST + "\nEdited in this PR.\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "feat: the pending record and the debt")
        sh(o, "git", "push", "-q", "-f", "origin", "feat")
        sh(self.co, "git", "fetch", "-q", "origin")

    def test_preview_refuses_a_closed_debt_whose_retire_check_is_red(self):
        self.pr_on_debt(1)
        self.host.state = "red: checks: fail"  # the head's CI is not green, so preview runs the Retire check itself
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 1, out)
        names_kind(self, out, "retire-target", "red")

    def test_confirm_with_red_ci_refuses_at_the_head_wait_before_any_claim_or_push(self):
        """CI's verdict on the head is the gate at confirm. A red head read refuses before the claim, and confirm runs no Retire check."""
        self.pr_on_debt(1)
        calls = self.stub_retire_check()
        self.host.state = "red: checks: fail"  # the head reads red: refused before any claim
        before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("nothing was claimed or pushed", out)
        self.assertIn("checks: fail", out, "the stop does not print the red check")
        self.assertEqual(calls, [], "confirm called the Retire check")
        self.assertEqual(self.refs(), before, "a refused confirm pushed")
        self.assertEqual(self.claims(), 0, "a refused confirm claimed a record number")
        self.assertFalse(getattr(self.host, "merged", False), "a refused confirm merged")
        self.assertFalse(self.lock_ref(), "a refused confirm kept the merge lock")

    def test_preview_passes_a_closed_debt_whose_retire_check_is_green(self):
        self.pr_on_debt(0)
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        self.assertIn("PREVIEW", out)
        self.assertNotIn("BLOCKED", out)

    def test_a_pr_that_closes_no_debt_previews_as_before(self):
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        self.assertIn("PREVIEW", out)
        self.assertNotIn("retire", out.lower())

    def test_an_edited_debt_is_not_a_close(self):
        self.pr_on_debt(1, closes=False)
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        self.assertIn("PREVIEW", out)
        self.assertNotIn("BLOCKED", out)

    def stub_retire_check(self):
        """Stand in for check_debt_retire.check: each call is recorded, and it finds nothing. -> the list of recorded calls."""
        import check_debt_retire
        calls = []

        def check(*args, **kwargs):
            calls.append((args, kwargs))
            return []

        patch = unittest.mock.patch.object(check_debt_retire, "check", check)
        patch.start()
        self.addCleanup(patch.stop)
        return calls

    def ci_closes_a_debt(self, state):
        """Scope: feat deletes the debt file, and the host reports `state` on the head."""
        self.assertIn("D\tdocs/debts/retire-target.md", sh(self.co, "git", "diff", "--name-status", "origin/main", "origin/feat"),
                      "scope: feat does not close the debt, so there is no close to judge")
        self.host.state = state
        self.assertEqual(self.host.head_state(7), state, "scope: the host does not report %s CI" % state)

    def green_ci_closes_a_debt(self):
        """Scope: feat deletes the debt file, and the host reports green CI on the head."""
        self.ci_closes_a_debt("green")

    def test_confirm_with_green_ci_never_calls_the_retire_check(self):
        """The Retire run moved into CI, so a host that reports green CI is not asked for the check at confirm, before the claim or after its wait."""
        self.pr_on_debt(1)  # the close's own Retire test is red: merge would refuse it if it still ran the check
        self.green_ci_closes_a_debt()
        calls = self.stub_retire_check()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, "scope: confirm did not reach its merge: " + out)
        self.assertTrue(getattr(self.host, "merged", False), "scope: confirm did not merge")
        self.assertEqual(calls, [], "confirm called the Retire check with green CI")

    def test_preview_with_green_ci_never_calls_the_retire_check(self):
        self.pr_on_debt(1)
        self.green_ci_closes_a_debt()
        calls = self.stub_retire_check()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, "scope: preview did not reach its verdict: " + out)
        self.assertEqual(calls, [], "preview called the Retire check with green CI")

    def test_preview_runs_the_retire_check_when_head_ci_is_pending(self):
        """Pending CI is not green, so preview runs the Retire check on the head. The close's own Retire test is red, so a real run would refuse it."""
        self.pr_on_debt(1)
        self.ci_closes_a_debt("pending: checks")
        calls = self.stub_retire_check()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, "scope: preview did not reach its verdict: " + out)
        self.assertEqual(len(calls), 1, "preview did not call the Retire check once with pending CI")

    def test_preview_runs_the_retire_check_when_head_ci_is_unknown(self):
        """An unknown read of the head's CI is not green, so preview runs the Retire check on the head. The close's own Retire test is red."""
        self.pr_on_debt(1)
        self.ci_closes_a_debt("unknown (a read of the head's checks failed)")
        calls = self.stub_retire_check()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, "scope: preview did not reach its verdict: " + out)
        self.assertEqual(len(calls), 1, "preview did not call the Retire check once with unknown CI")

    # The lock outlasts the long check that confirm runs, undo_check, which has no bound. Each check call is preceded by its own extend_for, so the
    # lock is never left to the take's fixed expiry under a check. confirm runs no debt check, because the Retire run runs in CI.

    LOCK_REFUSAL = "the fake lock refuses the extension"

    def recording_lock(self, events, stop_when=None):
        """A GitLock whose extend_for appends ("extend", wait) to `events`, then runs the real method. With `stop_when`, a call made while
        stop_when() is true raises NetStop instead: the lock cannot be extended. confirm reads the method with getattr, so the
        instance attribute is what it finds."""
        lock = merge.GitLock(self.co, now=lambda: self.now, pause=lambda s: None)
        real = lock.extend_for
        def extend_for(wait):
            events.append(("extend", wait))
            if stop_when and stop_when():
                raise merge.NetStop(self.LOCK_REFUSAL)
            return real(wait)
        lock.extend_for = extend_for
        return lock

    def spy_checks(self, events):
        """merge.undo_check and merge.debt_check append ("check", kind) to `events` at each call, then run the real check."""
        real_undo, real_debt = merge.undo_check, merge.debt_check
        def undo_spy(*a, **k):
            events.append(("check", "undo"))
            return real_undo(*a, **k)
        def debt_spy(*a, **k):
            events.append(("check", "debt"))
            return real_debt(*a, **k)
        for name, fn in (("undo_check", undo_spy), ("debt_check", debt_spy)):
            patch = unittest.mock.patch.object(merge, name, fn)
            patch.start()
            self.addCleanup(patch.stop)

    def spy_pushes(self, events):
        """merge.push_branch appends ("push", branch) to `events` at each push, then pushes. confirm's claim is the first push."""
        real = merge.push_branch
        def push(wt, branch, *a, **k):
            events.append(("push", branch))
            return real(wt, branch, *a, **k)
        patch = unittest.mock.patch.object(merge, "push_branch", push)
        patch.start()
        self.addCleanup(patch.stop)

    def confirm_closed_debt_under_spies(self, events):
        """A confirm of a PR that closes a debt, with each extension and check call logged in `events`. -> (rc, out)."""
        self.pr_on_debt(0)
        self.spy_checks(events)
        return self.run_merge("7", "--confirm", lock=self.recording_lock(events))

    def assert_claimed_and_undo_checked_twice(self, events, out):
        """Scope before subject (P7): the claim was pushed and merged, and the undo check ran twice, before the claim and inside prove. confirm of a
        ready PR runs no debt check (the Retire run runs in CI), so the debt check count is 0."""
        self.assertEqual(self.claims(), 1, out)
        self.assertTrue(getattr(self.host, "merged", False), out)
        self.assertEqual(events.count(("check", "debt")), 0, f"confirm ran a debt check, which ruling R2 removed from confirm (run order: {events})")
        self.assertGreaterEqual(events.count(("check", "undo")), 2, "the undo check ran fewer than twice, so the case misses the call inside prove")

    def test_confirm_of_a_ready_pr_runs_no_debt_check_and_extends_no_lock_for_one(self):
        """The Retire run runs in CI, so confirm runs no debt check and extends the lock for none. The
        debt-check length is patched to a value no undo extension uses, so an extension that carries it is a debt check's."""
        sentinel = 7777
        patch = unittest.mock.patch.object(merge, "debt_check_lock_seconds", lambda: sentinel, create=True)  # create: the name may go once no caller remains
        patch.start()
        self.addCleanup(patch.stop)
        events = []
        rc, out = self.confirm_closed_debt_under_spies(events)
        self.assertEqual(rc, 0, out)
        self.assert_claimed_and_undo_checked_twice(events, out)
        self.assertNotIn(sentinel, [wait for what, wait in events if what == "extend"],
                         f"confirm extended the lock by {sentinel} s, the debt-check length, before a check (run order: {events})")

    def test_confirm_extends_the_lock_for_3600_s_before_each_undo_check(self):
        events = []
        rc, out = self.confirm_closed_debt_under_spies(events)
        self.assertEqual(rc, 0, out)
        self.assert_claimed_and_undo_checked_twice(events, out)
        lacking = unextended_checks(events, "undo", 3600)
        self.assertEqual(lacking, [], f"an undo check at event {lacking} ran with no lock extension of 3600 s or more before it, since the check before it "
                                      f"(run order: {events}). undo_check has no time bound, and the lock can expire under it")

    def test_confirm_runs_under_a_lock_with_no_extend_for(self):  # control: green on the code before the change
        self.pr_on_debt(0)
        lock = NoExtendLock(self.co, now=lambda: self.now, pause=lambda s: None)
        rc, out = self.run_merge("7", "--confirm", lock=lock)
        self.assertEqual(rc, 0, out)
        self.assertNotIn("AttributeError", out, "a lock with no extend_for crashed confirm")
        self.assertTrue(getattr(self.host, "merged", False), out)

    def test_confirm_stops_before_the_undo_check_when_the_lock_cannot_be_extended(self):
        """confirm extends the lock before the undo check, its first call under the lock. The extension is refused: no check runs, no claim is pushed, nothing merges."""
        self.pr_on_debt(0)
        events = []
        self.spy_checks(events)
        rc, out = self.run_merge("7", "--confirm", lock=self.recording_lock(events, stop_when=lambda: True))
        checks = [e for e in events if e[0] == "check"]
        self.assertEqual(checks, [], f"a check ran after the lock extension was refused (run order: {events}). The extension stops the run before the check it covers")
        self.assertEqual(rc, 1, out)
        self.assertIn(self.LOCK_REFUSAL, out, "the refusal does not name the lock's stop")
        self.assertFalse(getattr(self.host, "merged", False), out)
        self.assertEqual(self.claims("feat"), 0, "a claim was pushed although the run stopped before the claim")
        self.assertFalse(self.lock_ref(), "the merge lock was left on origin")

    def test_prove_stops_before_the_checks_when_the_lock_cannot_be_extended_after_the_claim_push(self):
        """prove extends the lock after confirm pushes the claim. The extension is refused there: no check runs after the push, the claim stays
        on the branch, and nothing is reverted or merged."""
        self.pr_on_debt(0)
        events = []
        self.spy_checks(events)
        self.spy_pushes(events)
        pushed = lambda: any(e[0] == "push" for e in events)
        rc, out = self.run_merge("7", "--confirm", lock=self.recording_lock(events, stop_when=pushed))
        pushes = [i for i, e in enumerate(events) if e[0] == "push"]
        self.assertTrue(pushes, f"the claim was not pushed, so the run never reached prove (run order: {events})")
        late = [e for e in events[pushes[0] + 1:] if e[0] == "check"]
        self.assertEqual(late, [], f"a check ran after the claim push, past the lock extension that was refused (run order: {events})")
        self.assertEqual(rc, 1, out)
        self.assertIn(self.LOCK_REFUSAL, out, "the refusal does not name the lock's stop")
        self.assertNotIn("reverted on", out, "the claim was reverted although the run stopped on a refused lock extension")
        self.assertEqual(self.claims("feat"), 1, "the claim is not kept on the branch")
        self.assertFalse(getattr(self.host, "merged", False), out)
        self.assertFalse(self.lock_ref(), "the merge lock was left on origin")

class DraftPreview(Env):
    """`merge <pr>` with no --confirm: a draft is previewed, not refused. The silent-undo check runs on the head
    in every preview. A closed or merged PR is refused, and the check never runs on it."""

    def test_a_draft_preview_reports_a_dropped_line(self):
        SilentUndo.stale_feat(self)
        self.host.draft = True
        before = self.refs()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 1, out)
        self.assertIn("silently undoes", out)
        self.assertIn("first.md", out)
        self.assertIn("draft", out.lower())
        self.assertEqual(self.refs(), before)
        self.assertFalse(self.lock_ref())
        self.assertEqual(self.host.waits, [])
        self.assertEqual(self.worktrees(), 1)

    def test_a_ready_preview_reports_a_dropped_line(self):
        SilentUndo.stale_feat(self)
        before = self.refs()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 1, out)
        self.assertIn("silently undoes", out)
        self.assertIn("first.md", out)
        self.assertEqual(self.refs(), before)
        self.assertFalse(self.lock_ref())
        self.assertEqual(self.host.waits, [])

    def blocked_lines(self, out):
        return [l for l in out.splitlines() if l.startswith("BLOCKED: ")]

    def test_a_ready_preview_of_a_dropped_line_prints_one_blocked_line(self):
        SilentUndo.stale_feat(self)
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 1, out)
        blocked = self.blocked_lines(out)
        self.assertEqual(len(blocked), 1, out)
        self.assertIn("first.md", blocked[0])

    def test_a_draft_preview_of_a_dropped_line_prints_one_blocked_line(self):
        SilentUndo.stale_feat(self)
        self.host.draft = True
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 1, out)
        blocked = self.blocked_lines(out)
        self.assertEqual(len(blocked), 1, out)
        self.assertIn("first.md", blocked[0])

    def test_a_clean_draft_preview_passes_and_names_the_draft(self):
        self.host.draft = True
        before = self.refs()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        self.assertIn("PREVIEW", out)
        self.assertIn("Nothing was pressed", out)
        self.assertIn("draft", out.lower())
        self.assertNotIn("silently undoes", out)
        self.assertEqual(self.refs(), before)
        self.assertFalse(self.lock_ref())
        self.assertEqual(self.host.waits, [])

    def test_a_closed_or_merged_pr_is_refused_at_preview_and_the_check_never_runs(self):  # control
        real, calls = merge.undo_check, []
        def spy(wt, base_ref, unknown_ok="", pr_body="", run_state=None, retire_head=None):
            calls.append(base_ref)
            return real(wt, base_ref, unknown_ok, pr_body, run_state, retire_head)
        before = self.refs()
        with unittest.mock.patch.object(merge, "undo_check", spy):
            for state in ("CLOSED", "MERGED"):
                self.host.pr_state = state
                rc, out = self.run_merge("7")
                self.assertEqual(rc, 1, out)
                self.assertIn("the pull request is " + state, out)
        self.assertEqual(calls, [])
        self.assertEqual(self.refs(), before)


class PrBodyEscape(Env):
    """`Drops-lines: <path> -- <reason>` in the PR body excuses its path at preview, as a commit trailer does.
    A line with no reason, or one for another path, excuses nothing. Each use prints ALLOWED."""

    def preview(self):
        before = self.refs()
        rc, out = self.run_merge("7")
        self.assertEqual(self.refs(), before)
        self.assertEqual(self.host.waits, [])
        return rc, out

    def test_a_pr_body_line_excuses_its_path_at_preview(self):
        SilentUndo.stale_feat(self)
        self.host.body = "Drops-lines: docs/decisions/first.md -- the lines are dead"
        rc, out = self.preview()
        self.assertEqual(rc, 0, out)
        self.assertIn("ALLOWED docs/decisions/first.md: the lines are dead", out)
        self.assertNotIn("BLOCKED", out)

    def test_a_pr_body_line_without_a_reason_excuses_nothing(self):
        SilentUndo.stale_feat(self)
        for body in ("Drops-lines: docs/decisions/first.md", "Drops-lines: docs/decisions/first.md --"):
            with self.subTest(body=body):
                self.host.body = body
                rc, out = self.preview()
                self.assertEqual(rc, 1, out)
                self.assertIn("first.md", out)
                self.assertNotIn("ALLOWED", out)

    def test_a_pr_body_line_for_another_path_does_not_excuse(self):
        SilentUndo.stale_feat(self)
        self.host.body = "Drops-lines: docs/decisions/second.md -- wrong path"
        rc, out = self.preview()
        self.assertEqual(rc, 1, out)
        self.assertIn("first.md", out)
        self.assertNotIn("ALLOWED", out)

    def test_a_commit_trailer_still_excuses_its_path_at_preview(self):  # control
        SilentUndo.stale_feat(self)
        o = self.other
        sh(o, "git", "commit", "-q", "--allow-empty", "-m", "Drop them on purpose\n\nDrops-lines: docs/decisions/first.md -- the lines are dead")
        sh(o, "git", "push", "-q", "origin", "feat")
        rc, out = self.preview()
        self.assertEqual(rc, 0, out)
        self.assertIn("ALLOWED docs/decisions/first.md: the lines are dead", out)
    def test_the_undo_memo_is_not_reused_across_pr_bodies(self):
        SilentUndo.stale_feat(self)
        co = self.co
        sh(co, "git", "fetch", "-q", "origin")
        sh(co, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        excuse = "Drops-lines: docs/decisions/first.md -- the lines are dead"
        cwd = os.getcwd()
        os.chdir(co)
        try:
            for first, second in (("", excuse), (excuse, "")):
                with self.subTest(first=first, second=second):
                    merge.UNDO_MEMO.clear()
                    outcomes = []
                    for body in (first, second):
                        try:
                            with contextlib.redirect_stdout(io.StringIO()):
                                merge.undo_check(co, "origin/main", pr_body=body)
                            outcomes.append("ok")
                        except merge.Stop:
                            outcomes.append("refused")
                    want = ["ok" if b else "refused" for b in (first, second)]
                    self.assertEqual(outcomes, want)
        finally:
            os.chdir(cwd)
            merge.UNDO_MEMO.clear()


class StampEnv(unittest.TestCase):
    def test_the_stamp_child_never_sees_the_runners_ref(self):
        # On a push to main the runner sets GITHUB_REF=refs/heads/main. stamp would read it as the worktree's branch.
        seen = {}
        def fake(args, cwd=None, input=None, env=None):
            seen.update(env or {"__none__": "1"})
            return 0, ""
        with unittest.mock.patch.dict(os.environ, {"GITHUB_REF": "refs/heads/main", "GITHUB_BASE_REF": "main"}), \
             unittest.mock.patch.object(merge, "sh", fake):
            merge.node_stamp("/wt", ".github/stamp.json", "check", "origin/main")
        self.assertNotIn("__none__", seen)
        self.assertNotIn("GITHUB_REF", seen)
        self.assertNotIn("GITHUB_BASE_REF", seen)

class ClaimStderr(unittest.TestCase):
    """stamp.mjs --claim prints Record-claim: on stdout, but its regenerate step
    (npm) can write warn/notice lines on stderr. sh() concatenates stdout+stderr, so those land
    after the trailer. do_claim must find the trailer, not assume it is the last line."""
    def fake_sh(self, combined):
        # sh() itself does (r.stdout + r.stderr).strip(); patching sh means replicating that join.
        def fake(args, cwd=None, input=None, env=None):
            return 0, combined.strip()
        return fake

    def test_a_trailer_followed_by_npm_noise_on_stderr_is_still_read(self):
        out = "Record-claim: D-701\n" + "npm warn deprecated inflight@1.0.6: this module is not supported\nnpm notice new version of npm available"
        with unittest.mock.patch.object(merge, "sh", self.fake_sh(out)):
            trailer = merge.do_claim("/wt", ".github/stamp.json", "origin/main")
        self.assertEqual(trailer, "Record-claim: D-701")

    def test_nothing_to_claim_is_still_none(self):
        with unittest.mock.patch.object(merge, "sh", self.fake_sh("nothing pending.\n")):
            trailer = merge.do_claim("/wt", ".github/stamp.json", "origin/main")
        self.assertIsNone(trailer)

class UndoMemo(Env):
    """confirm() reads the silent-undo check twice: before the claim, and after the wait. When the head sha,
    origin/<base> and the default ref are the same at both reads, the second read reuses the first scan.
    One scan is one call of check_silent_undo.check. A scan can take about 35 min."""

    def counted(self, fn):
        sys.path.insert(0, os.path.join(HERE, "..", "lint"))
        import check_silent_undo as undo
        real_check, real_undo = undo.check, merge.undo_check
        scans, undos = [], []
        self.scan_runs, self.undo_runs = [], []  # the run index (0 for the first run) of each scan and each undo read

        def spy_check(*a, **k):
            scans.append(a[1])
            self.scan_runs.append(len(self.run_texts))
            return real_check(*a, **k)

        def spy_undo(wt, base_ref, unknown_ok="", pr_body="", run_state=None, retire_head=None):
            undos.append(base_ref)
            self.undo_runs.append(len(self.run_texts))
            return real_undo(wt, base_ref, unknown_ok, pr_body, run_state, retire_head)
        with unittest.mock.patch.object(undo, "check", spy_check), unittest.mock.patch.object(merge, "undo_check", spy_undo):
            res = fn()
        return res, len(scans), len(undos)

    def no_claim(self):
        """feat deletes its only pending record, so the run claims nothing and the head does not move."""
        sh(self.other, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(self.other, "git", "rm", "-q", "docs/decisions/second.md")
        sh(self.other, "git", "commit", "-qm", "no pending record left"); sh(self.other, "git", "push", "-q", "origin", "feat")

    def main_moves_in_the_run(self, fetch_co=False):
        """-> an action for in_wait: main gains a clean commit (moved.txt) after the run's first head read."""
        def move():
            sh(self.other, "git", "fetch", "-q", "origin")
            sh(self.other, "git", "checkout", "-q", "-B", "main", "origin/main")
            put(os.path.join(self.other, "moved.txt"), "main moved in the run\n")
            sh(self.other, "git", "add", "-A"); sh(self.other, "git", "commit", "-qm", "main moves in the run")
            sh(self.other, "git", "push", "-q", "origin", "main")
            if fetch_co:
                sh(self.co, "git", "fetch", "-q", "origin")
        return move

    def test_unchanged_head_base_and_default_scan_once(self):
        self.no_claim()
        (rc, out), scans, undos = self.counted(lambda: self.run_merge("7", "--confirm"))
        self.assertEqual(rc, 0, out)
        self.assertEqual(undos, 2, out)
        self.assertEqual(scans, 1, "scans %d, undo reads %d\n%s" % (scans, undos, out))

    def test_origin_base_moving_during_the_wait_scans_again(self):
        self.no_claim()
        self.in_wait(self.main_moves_in_the_run())
        (rc, out), scans, undos = self.counted(lambda: self.run_merge("7", "--confirm"))
        self.assertEqual(rc, 0, out)  # the scan runs again; the moved base is a clean merge, so the green run stands (rule M3)
        self.assertIn("The green run stands", out)
        self.assertEqual(undos, 2, out)
        self.assertEqual(scans, 2, "scans %d, undo reads %d\n%s" % (scans, undos, out))

    def test_default_ref_moving_during_the_wait_scans_again(self):
        self.no_claim()
        sh(self.other, "git", "fetch", "-q", "origin")
        sh(self.other, "git", "push", "-q", "origin", "origin/main:refs/heads/integ")
        self.host.base = "integ"
        self.in_wait(self.main_moves_in_the_run(fetch_co=True))
        (rc, out), scans, undos = self.counted(lambda: self.run_merge("7", "--confirm"))
        self.assertEqual(rc, 0, out)
        self.assertEqual(undos, 2, out)
        self.assertEqual(scans, 2, "scans %d, undo reads %d\n%s" % (scans, undos, out))

    def test_head_moving_for_the_claim_scans_again(self):
        (rc, out), scans, undos = self.counted(lambda: self.run_merge("7", "--confirm"))
        self.assertEqual(rc, 0, out)
        self.assertIn("pushed to feat", out)
        # per run: the claim run reads twice and scans twice, because the claim moved the head; the merge run reads twice and scans once,
        # its second read reusing the first scan (the memo is per run)
        self.assertEqual([self.undo_runs.count(i) for i in range(len(self.run_texts))], [2, 2], "undo reads per run, scans %d\n%s" % (scans, out))
        self.assertEqual([self.scan_runs.count(i) for i in range(len(self.run_texts))], [2, 1], "scans per run, undo reads %d\n%s" % (undos, out))


class MemoKeyRead(Env):
    """undo_check reads the memo key with git rev-parse. A timeout on that read leaves the history unread,
    so it must surface as the Unknown refusal, not crash the merge tool."""

    def test_a_timeout_on_the_memo_key_read_refuses_as_unknown(self):
        real_sh = merge.sh

        def slow(args, cwd=None, input=None, env=None):
            if "rev-parse" in args:
                raise subprocess.TimeoutExpired(args, 1)
            return real_sh(args, cwd=cwd, input=input, env=env)
        with unittest.mock.patch.object(merge, "sh", slow):
            with self.assertRaises(merge.Stop) as cm:
                merge.undo_check(self.co, "origin/main")
        self.assertIn("could not read the history", str(cm.exception))


class UnknownOverride(Env):
    """Unknown has a way out that does not depend on the check: a reason flag with a reason, logged. Claude may type it; the owner is not named as who types it."""
    FINDING = "stub.md: the finding a merge put back"

    def unreadable(self, problems=None):
        """check() raises an Unknown. With `problems`, the Unknown also carries them as its findings (.problems), as the octopus read does."""
        sys.path.insert(0, os.path.join(HERE, "..", "lint"))
        import check_silent_undo as undo
        def boom(*a, **k):
            e = undo.Unknown("git is older than 2.38")
            if problems is not None:
                e.problems, e.notes = list(problems), []
            raise e
        self.addCleanup(merge.UNDO_MEMO.clear)  # the memo keeps the Unknown itself
        return unittest.mock.patch.object(undo, "check", boom)

    def refusal_of(self, unknown_ok=""):
        """undo_check on the test checkout, with an Unknown that carries FINDING. -> the Stop it raised, or None when it returned."""
        with self.unreadable(problems=[self.FINDING]):
            try:
                merge.undo_check(self.co, "origin/main", unknown_ok=unknown_ok)
            except merge.Stop as e:
                return e
        return None

    def test_an_unknown_that_carries_findings_is_refused_as_dropped_and_the_reason_flag_does_not_lift_it(self):
        e = self.refusal_of(unknown_ok="octopus read it")
        self.assertIsNotNone(e, "the reason flag lifted an Unknown that carries findings: undo_check returned")
        self.assertIsInstance(e, merge.Dropped, "an Unknown that carries findings was not refused as a Dropped: %s" % type(e).__name__)
        self.assertNotIsInstance(e, merge.Unread, "an Unknown that carries findings was refused as Unread, which no refusal is")
        self.assertIn(self.FINDING, str(e))
        self.assertIn("git is older than 2.38", str(e), "the refusal does not carry the UNKNOWN's own message")

    def test_the_reason_flag_does_not_lift_an_unknown_that_carries_findings_at_the_merge(self):
        before = self.refs()
        with self.unreadable(problems=[self.FINDING]):
            rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", "octopus read it")
        self.assertEqual(rc, 1, out)
        self.assertIn(self.FINDING, out)
        self.assertEqual(self.refs(), before)
        self.assertFalse(self.lock_ref())

    def test_a_refusal_for_an_unknown_that_carries_findings_names_the_findings_and_the_unknown(self):
        with self.unreadable(problems=[self.FINDING]):
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn(self.FINDING, out)
        self.assertIn("git is older than 2.38", out)

    def test_an_unknown_with_no_findings_is_still_lifted_by_the_reason_flag(self):  # control
        with self.unreadable(problems=[]):
            got = merge.undo_check(self.co, "origin/main", unknown_ok="octopus read it")
        self.assertEqual(got, "octopus read it")

    def unreadable_after_the_claim(self):
        """The claim run's second silent-undo read, which prove() runs after the claim push, cannot read the history. Every other read passes."""
        return self.unreadable_read(run=0, read=2)

    def unreadable_read(self, run, read):
        """The silent-undo check raises Unknown on read number `read` (1-based) of run number `run` (0 for the claim run). Reads are
        counted per run, and every other read passes. A run's later undo_check reuses the memo of an Unknown, so it makes no second check call."""
        sys.path.insert(0, os.path.join(HERE, "..", "lint"))
        import check_silent_undo as undo
        real, calls = undo.check, {}
        def first_then_boom(*a, **k):
            r = len(self.run_texts)
            calls[r] = calls.get(r, 0) + 1
            if r == run and calls[r] == read:
                raise undo.Unknown("git is older than 2.38")
            return real(*a, **k)
        return unittest.mock.patch.object(undo, "check", first_then_boom)

    def test_unknown_refuses_and_names_the_flag(self):
        before = self.refs()
        with self.unreadable():
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("--undo-check-unknown-ok", out)
        self.assertEqual(self.refs(), before)
        self.assertFalse(self.lock_ref())

    def test_the_reason_flag_with_a_reason_goes_on_and_logs_it(self):
        with self.unreadable():
            rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", "octopus merge; history read by hand")
        self.assertEqual(rc, 0, out)
        self.assertIn("--undo-check-unknown-ok, reason: octopus merge; history read by hand", out, "the lift is logged with its flag and reason")
        self.assertNotIn("Owner override", out, "a reason flag Claude types is not an owner override")

    def test_the_silent_undo_refusal_names_a_reason_flag_not_the_owner(self):
        # the refusal line that names the flag must say it is a reason flag, and must not say the owner accepts the unknown
        with self.unreadable():
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        named = [l for l in out.splitlines() if "--undo-check-unknown-ok" in l]
        self.assertTrue(named, "the refusal names the flag")
        for line in named:
            self.assertNotIn("owner", line, "the refusal does not name the owner as who types the flag")
            self.assertIn("reason flag", line)

    def test_the_flag_with_no_reason_does_not_go_on(self):
        with self.unreadable():
            rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", " ")
        self.assertEqual(rc, 1)

    def test_the_flag_never_excuses_a_finding(self):
        SilentUndo.stale_feat(self)
        rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", "just let it through")
        self.assertEqual(rc, 1)
        self.assertIn("silently undoes", out)

    def test_the_pre_claim_unknown_stop_names_the_flag_not_the_no_override_line(self):
        # the reason flag lifts this stop, so the line that no override lifts is false here (before any claim is pushed)
        before = self.refs()
        with self.unreadable():
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("silent-undo check could not read the history", out)
        self.assertIn("--undo-check-unknown-ok", out)
        self.assertNotIn("No override lifts this refusal", out)
        self.assertEqual(self.refs(), before)

    def test_the_post_claim_unknown_stop_names_the_flag_not_the_no_override_line(self):
        # the read after the claim push runs through prove() and fail(); the same flag lifts it, so the no-override line is false
        with self.unreadable_after_the_claim():
            rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("pushed to feat", out, "the claim was pushed first, so this stop is the one after the claim")
        self.assertIn("silent-undo check could not read the history", out)
        self.assertIn("--undo-check-unknown-ok", out)
        self.assertNotIn("No override lifts this refusal", out)
        self.assertFalse(self.lock_ref())

class Identity(Env):
    def test_claim_commit_falls_back_when_only_the_email_is_set(self):
        info = self.host.pr(7)
        tmp, wt = merge.open_worktree(self.co, info, "main")
        try:
            sh(wt, "git", "config", "user.email", "x@x"); sh(wt, "git", "config", "user.useConfigOnly", "true")
            trailer = merge.do_claim(wt, ".github/stamp.json", "origin/main")
            with unittest.mock.patch.dict(os.environ):
                for k in ("GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL", "GIT_COMMITTER_NAME", "GIT_COMMITTER_EMAIL"):
                    os.environ.pop(k)
                merge.commit_claim(wt, trailer)
            self.assertEqual(sh(wt, "git", "log", "-1", "--format=%an"), "merge")
        finally:
            merge.drop_worktree(self.co, tmp, wt)

EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"

def dead_pid():
    p = subprocess.Popen([sys.executable, "-c", "pass"]); p.wait()
    return p.pid

class LockHolder(Env):
    """The lock names its holder; the Held text says alive, dead, or cannot tell."""
    def push_lock(self, message):
        sha = sh(self.co, "git", "commit-tree", EMPTY_TREE, "-m", message)
        sh(self.co, "git", "push", "-q", "origin", f"{sha}:refs/heads/merge-lock/main")

    def lock_msg(self):
        sh(self.co, "git", "fetch", "-q", "origin", "refs/heads/merge-lock/main")
        return sh(self.co, "git", "log", "-1", "--format=%B", "FETCH_HEAD")

    def peek(self, *args):
        """Run `merge 7 --confirm *args`. At the head's one read under the lock (Host.head_state), read the lock message and run a second merge.
        Returns (lock message, the second run's output). A run that never reaches that read gives ("", "")."""
        seen = {"msg": "", "second": ""}
        orig = self.host.head_state
        def read(n, sha=None):
            if not seen["msg"]:
                seen["msg"] = self.lock_msg()
                seen["second"] = self.run_merge("8", "--confirm")[1]
            return orig(n, sha)
        self.host.head_state = read
        try:
            self.run_merge("7", "--confirm", *args)
        except SystemExit:
            pass  # argparse refuses an unknown flag: the lock was never taken
        return seen["msg"], seen["second"]

    def old_message(self, expires):
        return f"merge lock\nexpires: {int(expires)}\nowner: abc123"

    def new_message(self, host, pid, expires=None, platform=None, boot=None):
        boot = merge.boot_stamp() if boot is None else boot  # "" writes no boot line, as a lock from before c189 has none
        return (f"merge lock\nexpires: {int(expires or self.now + 600)}\nowner: abc123\n"
                f"pr: 445\nbranch: b\nhost: {host}\npid: {pid}\nstarted: 1790000000\nplatform: {platform or sys.platform}"
                + (f"\nboot: {boot}" if boot else ""))

    def held(self, message):
        self.push_lock(message)
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        return out

    @windows_slice
    def test_the_lock_records_the_holder_and_a_second_run_sees_it_alive(self):
        msg, second = self.peek("--session", "S")
