def release_out(test, lock, token):
    out, err = io.StringIO(), io.StringIO()
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            lock.release("main", token)
    except Exception as e:
        test.fail(f"release raised {type(e).__name__}: {e}")
    return out.getvalue() + err.getvalue()

class ReleaseReports(Env):
    def test_a_normal_acquire_then_release_prints_no_line(self):
        tok = self.lock.acquire("main", 600)
        self.assertEqual(release_out(self, self.lock, tok), "")
        self.assertFalse(self.lock_ref())

    def test_gh_normal_acquire_then_release_prints_no_line(self):
        S = {}
        def api(self_, *a, **kw):
            p = a[2] if a[0] == "-X" else a[0]
            if a[:2] == ("-X", "DELETE"):
                S.pop("ref", None); return 0, ""
            if a[:2] == ("-X", "POST"):
                if p.endswith("git/commits"): return 0, "c1"
                if "ref" in S: return 1, "HTTP 422"
                S["ref"] = "c1"; return 0, "{}"
            if "/git/ref/heads/merge-lock/" in p:
                return (0, S["ref"]) if "ref" in S else (1, "HTTP 404: Not Found")
            if "/git/ref/heads/" in p: return 0, "head1"
            if "/git/commits/head1" in p: return 0, "tree1"
            if "/git/commits/c1" in p: return 0, "merge lock\nexpires: 2000\nowner: x"
            return 1, "unhandled " + p
        with unittest.mock.patch.object(merge.GhLock, "api", api):
            lock = merge.GhLock(now=lambda: 1000.0)
            tok = lock.acquire("main", 600)
            self.assertEqual(release_out(self, lock, tok), "")
            self.assertNotIn("ref", S)

    def test_git_release_says_so_when_the_delete_fails(self):
        tok = self.lock.acquire("main", 600)
        sh(self.co, "git", "remote", "set-url", "origin", os.path.join(self.t, "gone.git"))
        out = release_out(self, self.lock, tok)
        self.assertIn("the lock release failed", out)
        self.assertIn("merge --unlock", out)

    def test_git_release_says_so_when_the_token_was_replaced(self):
        tok = self.lock.acquire("main", 600)
        self.lock.unlock("main")
        merge.GitLock(self.other, now=lambda: self.now).acquire("main", 600)
        out = release_out(self, self.lock, tok)
        self.assertIn("not this run's", out)
        self.assertTrue(self.lock_ref())  # the other run's lock is left

class GhReleaseReports(unittest.TestCase):
    """GhLock.api is patched, so these run on Windows too."""
    def lock_with(self, sha_on_read, delete=(0, ""), read_fail=None):
        calls = []
        def api(self_, *a, **kw):
            calls.append(a)
            if a[:2] == ("-X", "DELETE"):
                return delete
            if "/git/ref/heads/merge-lock/" in a[0]:
                return read_fail or (0, sha_on_read)
            if "/git/commits/" in a[0]:
                return 0, "merge lock\nexpires: 2000\nowner: x"
            return 1, "unhandled"
        patcher = unittest.mock.patch.object(merge.GhLock, "api", api)
        patcher.start(); self.addCleanup(patcher.stop)
        return merge.GhLock(now=lambda: 1000.0, pause=lambda s: None), calls  # a retry pause is a no-op: a test never sleeps

    def test_delete_failure_is_reported(self):
        lock, _ = self.lock_with("tok", delete=(1, "HTTP 500 boom"))
        out = release_out(self, lock, "tok")
        self.assertIn("the lock release failed", out)
        self.assertIn("boom", out)

    def test_read_failure_is_reported_and_never_raises(self):
        lock, _ = self.lock_with("tok", read_fail=(1, "HTTP 500 down"))
        out = release_out(self, lock, "tok")
        self.assertIn("the lock release failed", out)

    def test_a_replaced_token_is_reported_and_nothing_is_deleted(self):
        lock, calls = self.lock_with("someone-else")
        out = release_out(self, lock, "tok")
        self.assertIn("not this run's", out)
        self.assertFalse([c for c in calls if c[:2] == ("-X", "DELETE")])

class NetErrorLines(unittest.TestCase):
    """merge.is_net on the output of one failed gh or git call: a wrapped 5xx or 429 line, and a JSON body with gh's
    error line after it. The false-match cases must not match: a PR title, a check name, a refusal that quotes a 5xx."""
    def test_a_wrapped_5xx_or_429_line_is_a_network_error(self):
        for out in ("failed to get runs: HTTP 502: 502 Bad Gateway (https://api.github.com/repos/o/r/actions/runs?head_sha=abc)",
                    "failed to get runs: HTTP 429: Too Many Requests (https://api.github.com/repos/o/r/actions/runs?head_sha=abc)"):
            with self.subTest(out=out):
                self.assertTrue(merge.is_net(1, out))

    def test_a_json_body_with_gh_error_line_after_it_is_a_network_error(self):
        self.assertTrue(merge.is_net(1, '{"message":"Server Error"}gh: Server Error (HTTP 502)'))

    def test_the_jq_html_body_parse_error_line_is_a_network_error(self):
        # `gh api --jq` on a 5xx HTML gateway page prints only this parse error. A title that quotes it is refusal text.
        self.assertTrue(merge.is_net(1, "invalid character '<' looking for beginning of value"))
        self.assertFalse(merge.is_net(1, 'GraphQL: Pull Request is not mergeable: #7 "invalid character \'<\' looking for beginning of value"'))

    def test_a_json_check_list_is_never_a_network_error(self):
        # gh's JSON answer names checks: a check named "build: HTTP 500 guard" is a red check, not a network error
        for out in ('[{"name":"build: HTTP 500 guard","bucket":"fail","link":""}]',
                    '[{"name":"checks: HTTP 502","bucket":"fail","link":""}]',
                    '[{"name":"EOF lint","bucket":"fail","link":""}]'):
            with self.subTest(out=out):
                self.assertFalse(merge.is_net(1, out))

    def test_a_pr_title_or_refusal_that_quotes_a_5xx_is_not_a_network_error(self):
        for out in ('GraphQL: Pull Request is not mergeable: #7 "Fix (HTTP 502 retry)"',
                    "GraphQL: Pull Request is not mergeable: #502 Bad Gateway fix",
                    'GraphQL: Pull Request is not mergeable: #7 "Fix: HTTP 502: proxy"'):
            with self.subTest(out=out):
                self.assertFalse(merge.is_net(1, out))

    def test_a_refusal_that_quotes_a_wrapped_5xx_or_429_line_is_not_a_network_error(self):
        # An unanchored `HTTP 5xx (url)` alternative would match refusal text. A real refusal must revert, not retry into NetStop.
        for out in ("X Pull request #7 is not mergeable: Retry on HTTP 502 (https://github.com/o/r/issues/12)",
                    "X Pull request #7 is not mergeable: Retry on HTTP 429 (https://github.com/o/r/issues/12)"):
            with self.subTest(out=out):
                self.assertFalse(merge.is_net(1, out))

    def test_a_real_server_error_or_wrapped_run_line_is_a_network_error(self):
        # The anchor must keep the 5xx and 429 forms gh really prints, bare or after `: `.
        for out in ("Server Error (HTTP 502)",
                    "HTTP 502 (https://api.github.com/repos/o/r/branches/main/protection/required_status_checks)",
                    "failed to get runs: HTTP 502 (https://api.github.com/repos/o/r/actions/runs?head_sha=abc)",
                    "HTTP 429: Too Many Requests",
                    "failed to get runs: HTTP 429: Too Many Requests (https://api.github.com/repos/o/r/actions/runs?head_sha=abc)"):
            with self.subTest(out=out):
                self.assertTrue(merge.is_net(1, out))

    def test_a_wrapped_5xx_with_no_space_after_its_colon_is_not_a_network_error(self):
        # The anchor must keep the space in `: ` before the message, or `HTTP 502:x (url)` matches.
        self.assertFalse(merge.is_net(1, "failed to get runs: HTTP 502:x (https://x)"))

    def test_each_network_string_a_retried_path_once_drove_is_a_network_error(self):
        """The one matcher, is_net, for every retried path: the git fetch after the claim push, a lost merge reply, the
        required-checks read and the merge reply. These rows held full git flows before (M13). One e2e case per path stays."""
        for out in ("fatal: unable to access 'https://github.com/shivinate7/claude-settings/': Empty reply from server",
                    "fatal: unable to access 'https://github.com/shivinate7/claude-settings/': GnuTLS recv error (-9): Error decoding the received TLS packet.",
                    "fatal: unable to access 'https://github.com/shivinate7/claude-settings/': Failed sending data to the peer",
                    "kex_exchange_identification: Connection closed by remote host\nfatal: Could not read from remote repository.",
                    NET_DEADLINE,
                    NET_REFUSED,
                    "gh: HTTP 503",
                    "gh: HTTP 500",
                    "HTTP 502 (https://api.github.com/repos/o/r/branches/main/protection/required_status_checks)",
                    '{"message":"Server Error"}gh: Server Error (HTTP 502)',
                    "HTTP 429: Too Many Requests"):
            with self.subTest(out=out):
                self.assertTrue(merge.is_net(1, out))

class RateLimitLines(unittest.TestCase):
    """merge.is_net on a rate-limited gh call. A rate-limit 403 is a network fault. A permission 403 is a refusal.
    These scan gh's output, not source text, so the string-opener cases of building-scanner-respects-strings do not apply."""
    def test_a_rate_limit_403_is_a_network_error(self):
        for out in (RATE_403, RATE_SECONDARY_403, RATE_GQL_403, RATE_API_403, RATE_API_SECONDARY_403, "Retry-After: 17\n" + RATE_403):
            with self.subTest(out=out[:70]):
                self.assertTrue(merge.is_net(1, out))

    def test_a_graphql_rate_limit_already_exceeded_is_a_network_error(self):
        self.assertTrue(merge.is_net(1, RATE_GQL_ALREADY))
        self.assertTrue(merge.is_net(1, "Retry-After: 17\n" + RATE_GQL_ALREADY))

    def test_a_403_that_is_not_a_rate_limit_is_not_a_network_error(self):
        for out in (PLAIN_403, PLAIN_403_BRANCH, PLAIN_403_API):  # the same shapes as the rate-limit texts
            with self.subTest(out=out[:70]):
                self.assertFalse(merge.is_net(1, out))

    def test_a_refusal_or_check_that_quotes_a_rate_limit_is_not_a_network_error(self):
        for out in ('GraphQL: Pull Request is not mergeable: #7 "Handle API rate limit exceeded"',
                    'GraphQL: Pull Request is not mergeable: #7 "Back off on a secondary rate limit"',
                    'GraphQL: Pull Request is not mergeable: #7 "Fix: HTTP 403: API rate limit exceeded"',
                    'GraphQL: Pull Request is not mergeable: #7 "Fix: GraphQL: API rate limit already exceeded"',
                    '[{"name":"API rate limit exceeded guard","bucket":"fail","link":""}]'):
            with self.subTest(out=out[:70]):
                self.assertFalse(merge.is_net(1, out))

class MethodSafeRetry(unittest.TestCase):
    """retry_net on a 5xx or network error resends only a safe method: GET, or a call its caller marks idempotent by design.
    A PUT merge that got a 502 may have landed, so it is never resent (lane retry-net-method-safe: a PUT merge went 4 times). A rate limit
    is a refusal that ran nothing, so any method still waits and retries. The method is the LAST -X of the command.
    A write with a `landed()` check (decision standing-merge-grant) is checked first: landed means no resend, not landed means resend, unknown means stop."""
    ERR = "failed to get runs: HTTP 502: 502 Bad Gateway (https://api.github.com/repos/o/r/pulls/7/merge)"

    def setUp(self):
        self.pauses, self.calls = [], 0

    def retry(self, reply, **kw):
        self.calls = 0
        def call():
            self.calls += 1
            return reply
        return merge.retry_net(call, self.pauses.append, **kw)

    def test_a_get_is_still_retried_on_a_502(self):
        self.assertEqual(self.retry((1, self.ERR), method="GET"), (1, self.ERR, 3))
        self.assertEqual(self.calls, 4)

    def test_a_put_or_post_or_patch_or_delete_is_resent_0_times_on_a_502(self):
        for method in ("PUT", "POST", "PATCH", "DELETE", "put"):
            with self.subTest(method=method):
                self.assertEqual(self.retry((1, self.ERR), method=method), (1, self.ERR, 0))
                self.assertEqual(self.calls, 1)
        self.assertEqual(self.pauses, [])

    def test_a_put_that_never_says_it_is_idempotent_is_not_resent_on_a_network_error(self):
        self.assertEqual(self.retry((1, NET_TLS), method="PUT"), (1, NET_TLS, 0))

    def test_a_write_that_landed_is_not_resent_and_reads_as_done(self):
        self.assertEqual(self.retry((1, self.ERR), method="PUT", landed=lambda: True), (0, "", 0))
        self.assertEqual(self.calls, 1)

    def test_a_write_that_did_not_land_is_resent_up_to_three_times(self):
        self.assertEqual(self.retry((1, self.ERR), method="PUT", landed=lambda: False), (1, self.ERR, 3))
        self.assertEqual(self.calls, 4)

    def test_a_write_that_did_not_land_goes_through_on_the_next_try(self):
        self.calls = 0
        def call():
            self.calls += 1
            return (1, self.ERR) if self.calls == 1 else (0, "{}")
        self.assertEqual(merge.retry_net(call, self.pauses.append, method="POST", landed=lambda: False), (0, "{}", 1))
        self.assertEqual(self.pauses, [merge.NET_PAUSE])

    def test_a_write_whose_check_cannot_tell_is_not_resent(self):
        self.assertEqual(self.retry((1, self.ERR), method="PUT", landed=lambda: None), (1, self.ERR, 0))
        self.assertEqual(self.calls, 1)

    def test_a_rate_limit_never_asks_the_check(self):
        asked = []
        self.assertEqual(self.retry((1, R429), method="PUT", landed=lambda: asked.append(1)), (1, R429, 3))
        self.assertEqual(asked, [])

    def test_acquire_takes_the_lock_when_the_ref_post_landed_with_a_lost_reply(self):  # a resend would read "already exists" as another run's lock
        state = {"ref": None}
        def sh(args, cwd=None, input=None, env=None):
            a = " ".join(args)
            if "git/ref/heads/merge-lock/" in a:
                return (0, state["ref"]) if state["ref"] else (1, "gh: Not Found (HTTP 404)")
            if "git/ref/heads/main" in a:
                return 0, "head1"
            if "git/commits/head1" in a:
                return 0, "tree1"
            if "-X POST" in a and "git/commits" in a:
                return 0, "c1"
            if "-X POST" in a and "git/refs" in a:
                state["ref"] = "c1"  # the ref is made, its reply is lost
                return 1, self.ERR
            return 1, "unhandled " + a
        lock = merge.GhLock(now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh):
            self.assertEqual(lock.acquire("main", 600), "c1")

    def merge_lost_reply(self, pr_reads, head="a" * 40):
        """Host.merge with every PUT answering a 502 and the PR reads `pr_reads` (one JSON dict per read, the last repeats). -> (puts, result or the stop raised)."""
        puts, reads = [], []
        def pr_json(d):
            base = {"number": 7, "head": {"sha": head, "ref": "feat"}, "base": {"ref": "main"}, "state": "open", "merged": False, "mergeable": True,
                    "mergeable_state": "clean", "merge_commit_sha": None}
            return json.dumps({**base, **d})
        def sh(args, cwd=None, input=None, env=None):
            a = " ".join(args)
            if "-X PUT" in a:
                puts.append(a)
                return 1, self.ERR
            reads.append(a)
            r = pr_reads[min(len(reads), len(pr_reads)) - 1]
            return (0, r) if isinstance(r, str) else (0, pr_json(r))  # a str is the raw reply
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh):
            try:
                got = host.merge(7, "squash", head)
            except (merge.NetStop, merge.Stop) as e:
                got = e
        return len(puts), got

    def test_a_merge_lost_to_a_502_that_reads_merged_at_this_head_is_sent_once_and_carries_on(self):
        puts, got = self.merge_lost_reply([{}, {"merged": True, "state": "closed", "merge_commit_sha": "m1"}])
        self.assertEqual((puts, got), (1, ("m1", "")))

    def test_a_merge_lost_to_a_502_that_reads_merged_at_another_head_is_sent_once_and_stops(self):  # not this run's merge: a resend is the incident
        puts, got = self.merge_lost_reply([{}, {"merged": True, "state": "closed", "merge_commit_sha": "m1", "head": {"sha": "b" * 40, "ref": "feat"}}])
        self.assertEqual(puts, 1)
        self.assertIsInstance(got, merge.Stop)
        self.assertNotIsInstance(got, merge.NetStop)

    def test_a_merge_lost_to_a_502_that_reads_closed_unmerged_is_sent_once_and_stops(self):
        puts, got = self.merge_lost_reply([{}, {"state": "closed"}])
        self.assertEqual(puts, 1)
        self.assertIsInstance(got, merge.NetStop)

    def test_a_merge_lost_to_a_502_that_reads_open_is_resent_up_to_three_times(self):
        puts, got = self.merge_lost_reply([{}])
        self.assertEqual(puts, 4)
        self.assertIsInstance(got, merge.NetStop)

    def test_a_merge_lost_to_a_502_whose_pr_read_is_not_json_is_sent_once(self):
        puts, got = self.merge_lost_reply([{}, "not json"])
        self.assertEqual(puts, 1)
        self.assertIsInstance(got, merge.NetStop)

    def test_a_merge_lost_to_a_502_whose_state_is_neither_open_nor_merged_is_sent_once(self):
        puts, got = self.merge_lost_reply([{}, {"state": "weird"}])
        self.assertEqual(puts, 1)
        self.assertIsInstance(got, merge.NetStop)

    def take_with_ref_reads(self, ref_reads):
        """GhLock.acquire where the ref POST answers a 502 and the ref reads `ref_reads` (each a (code, text), the last repeats). -> (ref POSTs, result or the stop raised)."""
        posts, reads = [], []
        def sh(args, cwd=None, input=None, env=None):
            a = " ".join(args)
            if "git/ref/heads/merge-lock/" in a:
                reads.append(a)
                return ref_reads[min(len(reads), len(ref_reads)) - 1] if len(reads) > 1 else (1, "gh: Not Found (HTTP 404)")  # the first read is acquire's own: no lock
            if "git/ref/heads/main" in a:
                return 0, "head1"
            if "git/commits/head1" in a:
                return 0, "tree1"
            if "-X POST" in a and "git/commits" in a:
                return 0, "c1"
            if "-X POST" in a and "git/refs" in a:
                posts.append(a)
                return (1, "gh: Reference already exists (HTTP 422)") if len(posts) > 1 else (1, self.ERR)
            return 1, "unhandled " + a
        lock = merge.GhLock(now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh):
            try:
                got = lock.acquire("main", 600)
            except (merge.NetStop, merge.Stop, merge.Held) as e:
                got = e
        return len(posts), got

    def test_a_lock_ref_post_lost_to_a_502_that_reads_another_runs_sha_is_sent_once_and_never_taken(self):
        posts, got = self.take_with_ref_reads([(0, "other-sha")])
        self.assertEqual(posts, 1)
        self.assertIsInstance(got, merge.NetStop)

    def test_a_lock_ref_post_lost_to_a_502_whose_ref_read_is_a_5xx_with_404_text_is_sent_once(self):
        posts, got = self.take_with_ref_reads([(1, "gh: Server Error (HTTP 502) https://api.github.com/repos/o/r/git/ref/heads/merge-lock/main/404")])
        self.assertEqual(posts, 1)
        self.assertIsInstance(got, merge.NetStop)

    def test_a_lock_ref_post_lost_to_a_502_that_reads_no_ref_is_resent_and_a_422_is_held(self):
        posts, got = self.take_with_ref_reads([(1, "gh: Not Found (HTTP 404)")])
        self.assertEqual(posts, 2)
        self.assertIsInstance(got, merge.Held)

    def test_an_idempotent_call_is_resent(self):
        self.assertEqual(self.retry((1, self.ERR), method="POST", idempotent=True), (1, self.ERR, 3))
        self.assertEqual(self.calls, 4)

    def test_a_put_is_still_retried_on_a_rate_limit_because_a_refusal_ran_nothing(self):
        self.assertEqual(self.retry((1, R429), method="PUT"), (1, R429, 3))
        self.assertEqual(self.calls, 4)
        self.assertEqual(self.pauses, [60, 300, 900])

    def test_the_last_x_names_the_method(self):
        for args, want in ((["api", "r", "-X", "GET", "-X", "PUT"], "PUT"), (["api", "r", "-X", "PUT", "-X", "GET"], "GET"),
                           (["api", "r", "-X", "put"], "PUT"), (["api", "r"], "GET"), (["run", "list"], "GET"),
                           (["api", "r", "-f", "a=b"], "POST"), (["api", "r", "--input", "f.json"], "POST"), (["api", "r", "--method=PATCH"], "PATCH")):
            with self.subTest(args=args):
                self.assertEqual(merge.net_method(args), want)

    def test_host_gh_sends_a_put_merge_once_on_a_502(self):
        calls = []
        def sh(args, cwd=None, input=None, env=None):
            calls.append(args)
            return 1, self.ERR
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh), self.assertRaises(merge.NetStop):
            host.gh(["api", "repos/o/r/pulls/7/merge", "-X", "GET", "-X", "PUT"])
        self.assertEqual(len(calls), 1)

    def test_net_method_reads_the_attached_and_long_forms(self):
        for args, want in ((["api", "r", "-XPUT"], "PUT"), (["api", "r", "-X=PATCH"], "PATCH"), (["api", "r", "--input=f.json"], "POST"),
                           (["api", "r", "--field=a=b"], "POST"), (["api", "r", "--raw-field=a=b"], "POST"), (["api", "r", "-fa=b"], "POST"),
                           (["api", "r", "-X", "GET", "-f", "a=b"], "GET"), (["api", "r", "-i", "--jq", ".x"], "GET")):
            with self.subTest(args=args):
                self.assertEqual(merge.net_method(args), want)

    def test_acquire_resends_the_lock_commit_post_after_a_502(self):  # the real call in GhLock.acquire: a commit no ref names, idempotent by design
        posts = []
        def sh(args, cwd=None, input=None, env=None):
            a = " ".join(args)
            if "git/ref/heads/merge-lock/" in a:
                return 1, "gh: Not Found (HTTP 404)"
            if "git/ref/heads/main" in a:
                return 0, "head1"
            if "git/commits/head1" in a:
                return 0, "tree1"
            if "-X POST" in a and "git/commits" in a:
                posts.append(a)
                return (1, self.ERR) if len(posts) == 1 else (0, "c1")
            if "-X POST" in a and "git/refs" in a:
                return 0, "{}"
            return 1, "unhandled " + a
        lock = merge.GhLock(now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh):
            self.assertEqual(lock.acquire("main", 600), "c1")
        self.assertEqual(len(posts), 2)

    def test_a_patch_flagged_idempotent_on_host_api_is_resent_after_a_502(self):  # a PATCH that sets a value: a resend writes the same value
        seq = [(1, self.ERR), (0, "{}")]
        calls = []
        def sh(args, cwd=None, input=None, env=None):
            calls.append(args)
            return seq[min(len(calls), len(seq)) - 1]
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: 1000.0, pause=self.pauses.append)
        reply = None
        with unittest.mock.patch.object(merge, "sh", sh):
            try:
                reply = host.api("pulls/7", method="PATCH", body={"body": "b"}, idempotent=True)
            except merge.NetStop:  # a 502 that is not resent stops the call: the count below names the cause
                pass
        self.assertEqual(len(calls), 2, "a PATCH flagged idempotent was not resent after its 502")
        self.assertEqual(reply[0], 0, "the resent PATCH flagged idempotent did not succeed")

    def test_host_gh_still_retries_a_get_on_a_502(self):
        calls = []
        def sh(args, cwd=None, input=None, env=None):
            calls.append(args)
            return 1, self.ERR
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: 1000.0, pause=self.pauses.append)
        with unittest.mock.patch.object(merge, "sh", sh), self.assertRaises(merge.NetStop):
            host.gh(["api", "repos/o/r/pulls/7", "-X", "GET"])
        self.assertEqual(len(calls), 4)


class RateLimitWait(unittest.TestCase):
    """retry_net and Host.gh on a rate-limited call: how many tries, and how long each wait is. The pause
    is a recorder, so nothing sleeps. A rate-limit text (403 or 429, any form) is retried 3 times. With no reset time from GitHub the waits are
    RATE_LADDER: 60, 300, 900 s. A reset time (a `Retry-After` header, in seconds) is the wait instead, capped at 900 s. Any other network error
    waits merge.NET_PAUSE. Before each rate wait the call runs Host.before_wait (confirm sets it to the lock's extend_for): it
    extends the lock past the wait, or raises NetStop, and then the call stops in place of the wait.
    Headers are read only from a `gh api -i` block: the reply starts with a status line, then the headers (gh_i builds one, in the shape gh 2.98.0
    prints). A header-like line anywhere else is text. Real `gh run list` has no -i, so on it the
    ladder is the only wait. These scan gh's output, not source text, so the string-opener cases of building-scanner-respects-strings do not apply."""
    NOW = 1000.0

    def setUp(self):
        self.pauses, self.calls = [], 0

    def replies(self, *seq):
        """Patch merge.sh so each gh call answers the next of `seq` (the last repeats). Counts them in self.calls."""
        self.calls = 0
        def sh(args, cwd=None, input=None, env=None):
            self.calls += 1
            return seq[min(self.calls, len(seq)) - 1]
        p = unittest.mock.patch.object(merge, "sh", sh)
        p.start(); self.addCleanup(p.stop)

    def host(self):
        return merge.Host(required=["checks"], base="main", minute=60, now=lambda: self.NOW, pause=self.pauses.append)

    def clocked_host(self, before_wait=None):
        """-> (host, clock). The pauses move the clock on. `before_wait` is what confirm hands the host once the lock is taken: the lock's extend_for
        (see LockExtensionReachesHost). It gets the wait in seconds."""
        clock = Clock(self.NOW)
        host = merge.Host(required=["checks"], base="main", minute=60, now=clock.now, pause=clock.pause)
        host.before_wait = before_wait
        return host, clock

    def retry(self, *seq):
        """-> merge.retry_net's result over the replies `seq`."""
        self.calls = 0
        def call():
            self.calls += 1
            return seq[min(self.calls, len(seq)) - 1]
        return merge.retry_net(call, self.pauses.append)

    # retry_net: the tries and the ladder
    def test_a_rate_limit_403_is_retried_with_the_rate_wait(self):
        self.assertEqual(self.retry((1, RATE_403), (1, RATE_SECONDARY_403), (0, "[]")), (0, "[]", 2))
        self.assertEqual(self.pauses, [60, 300])  # a rate limit waits the ladder, not NET_PAUSE

    def test_the_rate_waits_with_no_reset_are_60_300_900_seconds(self):  # the three waits, 21 minutes in all
        self.assertEqual(self.retry(*([(1, RATE_403)] * 3), (0, "[]")), (0, "[]", 3))
        self.assertEqual(self.pauses, [60, 300, 900])

    def test_a_graphql_rate_limit_already_exceeded_is_retried_with_the_rate_wait(self):
        self.assertEqual(self.retry((1, RATE_GQL_ALREADY), (0, "[]")), (0, "[]", 1))
        self.assertEqual(self.pauses, [60])

    def test_a_rate_limit_403_that_never_clears_is_tried_four_times(self):
        self.assertEqual(self.retry((1, RATE_403)), (1, RATE_403, 3))
        self.assertEqual(self.calls, 4)  # one try and three retries
        self.assertEqual(self.pauses, [60, 300, 900])

    def test_a_429_is_retried_with_the_rate_wait(self):
        self.assertEqual(self.retry((1, R429), (0, "[]")), (0, "[]", 1))
        self.assertEqual(self.pauses, [60])

    def test_a_plain_403_is_not_retried(self):  # (d): green before the lane, a guard
        for out in (PLAIN_403, PLAIN_403_BRANCH, PLAIN_403_API):
            with self.subTest(out=out[:70]):
                self.pauses.clear()
                self.assertEqual(self.retry((1, out), (0, "[]")), (1, out, 0))
                self.assertEqual(self.pauses, [])

    def test_a_plain_network_error_waits_the_normal_pause_whatever_its_headers(self):  # the NET_PAUSE half of the rule: a guard, green before the lane
        for out in (NET_TLS, "failed to get runs: HTTP 502: 502 Bad Gateway (https://api.github.com/repos/o/r/actions/runs?head_sha=abc)",
                    "Retry-After: 120\n" + NET_TLS,
                    gh_i(502, '{"message":"Server Error"}gh: Server Error (HTTP 502)', Retry_After=120)):  # a 5xx is not a rate limit: its Retry-After is no rate wait
            with self.subTest(out=out[:40]):
                self.pauses.clear()
                self.assertEqual(self.retry((1, out), (0, "[]")), (0, "[]", 1))
                self.assertEqual(self.pauses, [merge.NET_PAUSE])

    # retry_net: a reset time from GitHub is the wait. It is read from a `gh api -i` block only.
    def test_a_retry_after_in_a_gh_i_block_is_the_rate_wait(self):
        for body in (RATE_API_403, RATE_API_SECONDARY_403):
            for secs in (5, 120, 600):  # below the first rung, between the rungs, above the second
                with self.subTest(body=body[:40], retry_after=secs):
                    self.pauses.clear()
                    self.assertEqual(self.retry((1, gh_i(403, body, Retry_After=secs)), (0, "[]")), (0, "[]", 1))
                    self.assertEqual(self.pauses, [secs])

    def test_a_retry_after_name_is_read_in_any_case(self):
        self.assertEqual(self.retry((1, gh_i(403, RATE_API_403, Retry_After=17).replace("Retry-After", "retry-after")), (0, "[]")), (0, "[]", 1))
        self.assertEqual(self.pauses, [17])

    def test_a_retry_after_over_900_seconds_waits_900(self):  # the cap: 15 minutes
        for secs in (900, 901, 3600, 86400):
            with self.subTest(retry_after=secs):
                self.pauses.clear()
                self.assertEqual(self.retry((1, gh_i(403, RATE_API_SECONDARY_403, Retry_After=secs)), (0, "[]")), (0, "[]", 1))
                self.assertEqual(self.pauses, [900])

    def test_each_retry_honors_its_own_retry_after(self):
        seq = [(1, gh_i(403, RATE_API_403, Retry_After=s)) for s in (30, 45, 600)]
        self.assertEqual(self.retry(*seq, (0, "[]")), (0, "[]", 3))  # three retries, then the call goes through
        self.assertEqual(self.pauses, [30, 45, 600])

    def test_an_unreadable_retry_after_is_never_a_negative_or_an_oversized_wait(self):  # a guard: the exact wait is free, bounded by 0 and 900
        for value in ("soon", "-5", "0", ""):
            with self.subTest(retry_after=value):
                self.pauses.clear()
                self.assertEqual(self.retry((1, gh_i(403, RATE_API_403, Retry_After=value)), (0, "[]")), (0, "[]", 1))
                self.assertEqual(len(self.pauses), 1)
                self.assertTrue(0 <= self.pauses[0] <= 900, self.pauses)

    def test_a_header_like_line_outside_a_gh_i_block_never_changes_the_rate_wait(self):  # a guard: no status line ahead of it, so it is text, not a header
        for text in (R429, RATE_403, RATE_SECONDARY_403, RATE_GQL_ALREADY):
            for header in ("Retry-After: 5", "retry-after: 17", "Retry-After: 600"):
                with self.subTest(text=text[:40], header=header):
                    self.pauses.clear()
                    self.assertEqual(self.retry((1, header + "\n" + text), (0, "[]")), (0, "[]", 1))
                    self.assertEqual(self.pauses, [60])

    # Host.gh: no gh command it runs prints headers, so a header-like line is text, near, far or past.
    def test_a_header_like_reset_time_outside_a_gh_i_block_never_changes_the_rate_wait_on_a_429_or_a_rate_limit_403(self):  # a guard
        for text in (R429, RATE_403):
            for header in (f"X-Ratelimit-Reset: {int(self.NOW) + 5}", f"X-Ratelimit-Reset: {int(self.NOW) + 23}",
                           f"X-RateLimit-Reset: {int(self.NOW) + 3600}"):
                with self.subTest(text=text[:40], header=header):
                    self.pauses.clear()
                    self.replies((1, header + "\n" + text), (0, "[]"))
                    self.assertEqual(self.host().gh(["run", "list"]), (0, "[]"))
                    self.assertEqual(self.pauses, [60])

    def test_a_header_like_reset_time_already_past_waits_the_rate_wait_never_a_negative_time(self):  # a guard
        self.replies((1, f"X-Ratelimit-Reset: {int(self.NOW) - 100}\n" + R429), (0, "[]"))
        self.host().gh(["run", "list"])
        self.assertEqual(self.pauses, [60])

    def test_a_rate_limit_waits_the_rate_wait_whatever_its_timestamp_says(self):
        self.replies((1, RATE_403), (0, "[]"))  # "timestamp 2026-10-14 12:26:42 UTC" is the request's time, not a reset
        self.host().gh(["run", "list"])
        self.assertEqual(self.pauses, [60])

    def test_a_rate_limit_that_never_clears_is_a_net_stop_after_three_retries(self):  # (e)
        self.replies((1, RATE_403))
        with self.assertRaises(merge.NetStop) as cm:
            self.host().gh(["run", "list"])
        self.assertEqual(self.calls, 4)
        self.assertEqual(self.pauses, [60, 300, 900])
        self.assertIn("API rate limit exceeded", str(cm.exception))  # the stop shows gh's own words

    def test_a_plain_403_is_returned_at_once_by_host_gh(self):  # (d): a guard
        self.replies((1, PLAIN_403))
        self.assertEqual(self.host().gh(["run", "list"]), (1, PLAIN_403))
        self.assertEqual((self.calls, self.pauses), (1, []))

    def test_a_rate_wait_in_host_gh_prints_one_line_before_the_wait(self):
        self.replies((1, RATE_403), (0, "[]"))
        buf, snapshots = io.StringIO(), []
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: self.NOW, pause=lambda s: snapshots.append(buf.getvalue()))
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            self.assertEqual(host.gh(["run", "list"]), (0, "[]"))
        assert_one_rate_wait_line(self, buf.getvalue(), snapshots)

    def test_each_rate_wait_in_host_gh_prints_its_own_line_naming_the_call_and_the_wait(self):
        self.replies(*([(1, RATE_403)] * 3), (0, "[]"))
        buf, snapshots = io.StringIO(), []
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: self.NOW, pause=lambda s: snapshots.append(buf.getvalue()))
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            self.assertEqual(host.gh(["run", "list"]), (0, "[]"))
        assert_rate_wait_lines(self, buf.getvalue(), snapshots, [60, 300, 900], "gh run list")

    def test_a_plain_403_prints_no_wait_line(self):  # control
        self.replies((1, PLAIN_403))
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            self.assertEqual(self.host().gh(["run", "list"]), (1, PLAIN_403))
        self.assertNotRegex(buf.getvalue(), r"(?i)\bwait")

    # Host.gh and the lock: before_wait runs before each rate wait and decides it. The clock moves on with each pause, so the waits add up as they do in a run.
    def test_before_wait_runs_before_each_rate_wait_and_the_merge_goes_on(self):
        seen = []
        host, clock = self.clocked_host(before_wait=lambda wait: seen.append((wait, clock.now(), list(clock.pauses))))
        self.replies(*([(1, RATE_403)] * 3), (0, "[]"))
        self.assertEqual(host.gh(["run", "list"]), (0, "[]"))
        self.assertEqual(clock.pauses, [60, 300, 900])
        self.assertEqual(seen, [(60, self.NOW, []), (300, self.NOW + 60, [60]), (900, self.NOW + 360, [60, 300])])  # the wait, the clock and the pauses so far: each hook call comes before its own pause

    def test_host_gh_stops_with_a_net_stop_when_the_lock_cannot_be_extended_for_a_wait(self):
        def refuse(wait):
            if wait == 900:
                raise merge.NetStop("cannot extend the merge lock on main for a wait of 900 s. Run again.")
        host, clock = self.clocked_host(before_wait=refuse)
        self.replies((1, RATE_403))
        with self.assertRaises(merge.NetStop) as cm:
            host.gh(["run", "list"])
        self.assertEqual(clock.pauses, [60, 300])
        self.assertEqual(self.calls, 3)  # no fourth try: the stop comes in place of the third wait
        self.assertRegex(str(cm.exception), r"(?i)merge lock")  # the stop says why: the lock could not be extended
        self.assertIn("API rate limit exceeded", str(cm.exception))  # and shows gh's own words

    def test_host_gh_never_starts_a_rate_wait_when_the_first_extension_fails(self):
        def refuse(wait):
            raise merge.NetStop("cannot extend the merge lock on main for a wait of 60 s. Run again.")
        host, clock = self.clocked_host(before_wait=refuse)
        self.replies((1, RATE_403))
        with self.assertRaises(merge.NetStop) as cm:
            host.gh(["run", "list"])
        self.assertEqual((clock.pauses, self.calls), ([], 1))
        self.assertRegex(str(cm.exception), r"(?i)merge lock")

    def test_a_plain_network_error_never_runs_before_wait(self):  # a guard: only a rate wait needs the lock extended; a 5 s network pause is inside any lock
        calls = []
        host, clock = self.clocked_host(before_wait=calls.append)
        self.replies((1, NET_TLS), (0, "[]"))
        self.assertEqual(host.gh(["run", "list"]), (0, "[]"))
        self.assertEqual((calls, clock.pauses), ([], [merge.NET_PAUSE]))

    # (f) two helpers the extension leans on: the header block of an empty reply, and a whole-second wait
    def test_a_gh_i_reply_with_headers_and_no_body_has_an_empty_body(self):  # the empty body leaves no blank line after the headers
        for out in ("HTTP/2 200\nx: y", "HTTP/2.0 204 No Content\r\nX-Y: z\r\n"):
            with self.subTest(out=out):
                headers, body = merge.split_headers(out)
                self.assertEqual(body, "")
                self.assertEqual(len(headers), 1, headers)
        self.assertEqual(merge.split_headers("HTTP/2 200\nx: y"), ({"x": "y"}, ""))

    def test_a_reply_with_a_blank_line_still_splits_at_it(self):  # a guard: the empty-body rule leaves the normal block alone
        self.assertEqual(merge.split_headers("HTTP/2.0 403 Forbidden\r\nRetry-After: 17\r\n\r\nbody\nmore"), ({"retry-after": "17"}, "body\nmore"))

    def test_the_rate_wait_is_a_whole_number_of_seconds_whatever_the_clock_reads(self):
        reset = {"x-ratelimit-remaining": "0", "x-ratelimit-reset": "1100"}
        for now, want in ((1000.0, 100), (1000.4, 100), (1000.6, 100), (999.5, 101)):  # 99.4 s, 99.6 s and 100.5 s round up
            with self.subTest(now=now):
                got = merge.rate_wait(reset, 1, now)
                self.assertEqual((got, type(got)), (want, int))
        got = merge.rate_wait({"retry-after": "12"}, 1, 1000.5)
        self.assertEqual((got, type(got)), (12, int))
        got = merge.rate_wait({}, 2, 1000.5)
        self.assertEqual((got, type(got)), (300, int))  # the ladder rung
        got = merge.rate_wait({"x-ratelimit-remaining": "0", "x-ratelimit-reset": "9999"}, 1, 1000.5)
        self.assertEqual((got, type(got)), (900, int))  # the cap

class GhLockReadRetry(unittest.TestCase):
    """GhLock.read on a network error: retried as GitLock is. merge.sh is the only seam,
    so the test holds wherever the retry sits, in read or in api."""
    def run_read(self, replies):
        """The ref reads answer `replies` in order, the last repeats. -> the read's result. self.reads and self.pauses count the calls."""
        seq, self.reads, self.pauses = list(replies), 0, []
        def fake_sh(args, cwd=None, input=None, env=None):
            args = without_include(args)
            if args[:2] == ["gh", "api"] and "/git/ref/heads/merge-lock/" in args[2]:
                self.reads += 1
                return seq.pop(0) if len(seq) > 1 else seq[0]
            if args[:2] == ["gh", "api"] and "/git/commits/" in args[2]:
                return 0, "merge lock\nexpires: 2000\nowner: x"  # a live lock, held until 2000
            return 1, "unhandled " + " ".join(args)
        with unittest.mock.patch.object(merge, "sh", fake_sh):
            lock = merge.GhLock(now=lambda: 1000.0)
            lock.pause = self.pauses.append
            return lock.read("main")

    def read_that_must_not_stop(self, replies):
        try:
            return self.run_read(replies)
        except merge.Stop as e:
            self.fail(f"GhLock.read stopped on a network error after {self.reads} read(s): {e}")

    def test_a_transient_gh_server_error_on_the_lock_read_is_retried_and_the_read_succeeds(self):
        got = self.read_that_must_not_stop([(1, "gh: Server Error (HTTP 502)"), (0, "sha1")])
        self.assertEqual(got[0], "sha1")
        self.assertEqual(self.reads, 2)
        self.assertEqual(len(self.pauses), 1)

    def test_a_gh_server_error_that_keeps_failing_on_the_lock_read_is_a_net_stop_after_three_retries(self):
        try:
            self.run_read([(1, "gh: Server Error (HTTP 502)")])
        except merge.NetStop:
            pass
        except merge.Stop as e:
            self.fail(f"a network error stopped the lock read as a plain Stop, not a NetStop: {e}")
        else:
            self.fail("GhLock.read returned without a stop")
        self.assertEqual(self.reads, 4)  # one try and three retries
        self.assertEqual(len(self.pauses), 3)

    def test_a_404_on_the_lock_read_means_no_lock_and_is_not_retried(self):
        self.assertIsNone(self.read_that_must_not_stop([(1, "gh: Not Found (HTTP 404)")]))
        self.assertEqual(self.reads, 1)
        self.assertEqual(self.pauses, [])

class GitLockReadExhaustion(unittest.TestCase):
    """GitLock.read on a failing ls-remote. A network text stops with NetStop after three retries. Any other text stops at once."""
    def read_fails(self, reply):
        """-> (the Stop the read raised, its ls-remote calls, its retry pauses)."""
        calls, pauses = [], []
        def fake_git(cwd, *a, input=None):
            calls.append(a)
            return reply
        with unittest.mock.patch.object(merge, "git", fake_git):
            lock = merge.GitLock("unused", now=lambda: 1000.0, pause=pauses.append)
            with self.assertRaises(merge.Stop) as cm:
                lock.read("main")
        return cm.exception, calls, pauses

    def test_a_network_text_on_the_lock_read_is_a_net_stop_after_three_retries(self):
        exc, calls, pauses = self.read_fails((1, NET_HOST))
        self.assertIsInstance(exc, merge.NetStop, str(exc))
        self.assertEqual(len(calls), 4, calls)  # one try and three retries
        self.assertEqual(len(pauses), 3)

    def test_fatal_not_a_repository_on_the_lock_read_is_a_plain_stop_after_one_call(self):
        exc, calls, pauses = self.read_fails((128, "fatal: not a repository (or any of the parent directories): .git"))
        self.assertNotIsInstance(exc, merge.NetStop)
        self.assertEqual(len(calls), 1, calls)
        self.assertEqual(pauses, [])

@windows_slice
class ResolveProgram(unittest.TestCase):
    """resolve_program (merge.py): bash never resolves under System32; a bare name finds its .cmd shim."""
    @unittest.skipUnless(os.name == "nt", "the System32 WSL stub is a Windows case")
    def test_bash_skips_system32(self):
        t = tempfile.mkdtemp(prefix="test-resolve-", dir=run_folder()); self.addCleanup(shutil.rmtree, t, True)
        sysroot = os.path.join(t, "Win"); good = os.path.join(t, "good")
        for d in (os.path.join(sysroot, "System32"), good):
            os.makedirs(d); put(os.path.join(d, "bash.exe"), "x")
        env = {"PATH": os.pathsep.join([os.path.join(sysroot, "System32"), good]), "SystemRoot": sysroot,
               "ProgramFiles": os.path.join(t, "none")}
        self.assertEqual(merge.resolve_program("bash", env), os.path.join(good, "bash.exe"))

    @unittest.skipUnless(os.name == "nt", "PATHEXT lookup of a .cmd shim is a Windows case")
    def test_a_bare_name_finds_its_cmd_shim(self):
        t = tempfile.mkdtemp(prefix="test-resolve-", dir=run_folder()); self.addCleanup(shutil.rmtree, t, True)
        put_shim(os.path.join(t, "fakeprog"), "x")
        got = merge.resolve_program("fakeprog", {"PATH": t})
        self.assertEqual(os.path.normcase(got), os.path.normcase(os.path.join(t, "fakeprog.cmd")))

    def test_the_program_files_git_bash_wins_over_system32(self):
        t = tempfile.mkdtemp(prefix="test-resolve-", dir=run_folder()); self.addCleanup(shutil.rmtree, t, True)
        sysroot = os.path.join(t, "Win"); pf = os.path.join(t, "PF")
        git_bash = os.path.join(pf, "Git", "bin", "bash.exe")
        for f in (os.path.join(sysroot, "System32", "bash.exe"), git_bash):
            os.makedirs(os.path.dirname(f)); put(f, "x")
        env = {"PATH": os.path.join(sysroot, "System32"), "SystemRoot": sysroot, "ProgramFiles": pf}
        with unittest.mock.patch.object(merge.os, "name", "nt"):
            self.assertEqual(merge.resolve_program("bash", env), git_bash)

@windows_slice
@unittest.skipUnless(os.name == "nt", "pid_alive's kernel32 branches exist only on Windows")
class PidAlive(unittest.TestCase):
    """pid_alive (merge.py) on Windows, with kernel32 faked so it runs on any OS."""
    def probe(self, handle, last_error=0, exit_code=259):
        k = unittest.mock.Mock()
        k.OpenProcess.return_value = handle
        k.GetExitCodeProcess.side_effect = lambda h, ref: (setattr(ref._obj, "value", exit_code), 1)[1]
        with unittest.mock.patch.object(merge.os, "name", "nt"), \
             unittest.mock.patch("ctypes.WinDLL", create=True, return_value=k) as k_loader, \
             unittest.mock.patch("ctypes.get_last_error", create=True, return_value=last_error):
            result = merge.pid_alive(1234)
        k_loader.assert_called_once_with("kernel32", use_last_error=True)
        return result, k

    def test_access_denied_reads_alive(self):
        alive, k = self.probe(0, last_error=5)
        self.assertTrue(alive)
        k.GetExitCodeProcess.assert_not_called()

    def test_a_process_that_exited_reads_dead_and_its_handle_is_closed(self):
        alive, k = self.probe(77, exit_code=1)
        self.assertFalse(alive)
        k.CloseHandle.assert_called_once_with(77)

    def test_a_still_active_process_reads_alive_and_its_handle_is_closed(self):
        alive, k = self.probe(77, exit_code=259)
        self.assertTrue(alive)
        k.CloseHandle.assert_called_once_with(77)

@windows_slice
class SliceSelector(unittest.TestCase):
    """MERGE_TESTS=windows-slice keeps only the marked tests; no value keeps all; an unknown value stops."""
    def all_tests(self):
        return unittest.defaultTestLoader.loadTestsFromModule(sys.modules[__name__])

    def marked(self, t):
        return bool(t.__class__.__dict__.get("_windows_slice") or getattr(getattr(t, t._testMethodName), "_windows_slice", False))

    def test_the_slice_keeps_only_marked_tests_and_all_of_them(self):
        full = list(iter_tests(self.all_tests()))
        got = list(iter_tests(select_tests(self.all_tests(), "windows-slice")))
        self.assertTrue(0 < len(got) < len(full), (len(got), len(full)))
        self.assertTrue(all(self.marked(t) for t in got))
        self.assertEqual(len(got), sum(self.marked(t) for t in full))

    def test_the_slice_holds_the_windows_probe_and_the_bash_resolver_cases(self):
        """The exact slice, bar this class. Dropping or adding a mark must change this list on purpose."""
        got = {f"{t.__class__.__name__}.{t._testMethodName}" for t in iter_tests(select_tests(self.all_tests(), "windows-slice"))
               if t.__class__.__name__ != "SliceSelector"}
        self.assertEqual(got, {
            "ClaudeMdFlag.test_a_name_outside_cp1252_on_a_piped_stdout_still_flags_and_runs_every_step_after_the_merge",
            "Flow.test_afterMerge_runs_in_git_bash_not_the_wsl_stub",
            "Flow.test_full_merge_claims_pushes_merges_syncs_cleans",
            "GhHalf.test_an_empty_required_list_is_refused",
            "LockHolder.test_a_lock_with_no_platform_line_reads_cannot_tell_never_dead",
            "LockHolder.test_a_lock_on_this_host_whose_pid_is_gone_is_taken_over_with_one_line",
            "LockHolder.test_the_lock_records_the_holder_and_a_second_run_sees_it_alive",
            "LockHolder.test_the_same_host_name_on_another_platform_reads_cannot_tell_never_dead",
            "LockHolder.test_windows_liveness_never_calls_os_kill",
            "PidAlive.test_a_process_that_exited_reads_dead_and_its_handle_is_closed",
            "PidAlive.test_a_still_active_process_reads_alive_and_its_handle_is_closed",
            "PidAlive.test_access_denied_reads_alive",
            "ResolveProgram.test_a_bare_name_finds_its_cmd_shim",
            "ResolveProgram.test_bash_skips_system32",
            "ResolveProgram.test_the_program_files_git_bash_wins_over_system32"})

    def test_no_value_keeps_every_test(self):
        full = len(list(iter_tests(self.all_tests())))
        self.assertEqual(len(list(iter_tests(select_tests(self.all_tests(), "")))), full)

    def test_an_unknown_value_fails_loudly_and_runs_nothing(self):
        with self.assertRaises(SystemExit) as cm:
            select_tests(self.all_tests(), "windows_slice")
        self.assertIn("MERGE_TESTS", str(cm.exception))
        r = subprocess.run([sys.executable, os.path.abspath(__file__)], capture_output=True, text=True,
                           env=dict(os.environ, MERGE_TESTS="bogus"), timeout=60)
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("MERGE_TESTS", r.stdout + r.stderr)
        self.assertNotIn("Ran ", r.stdout + r.stderr)

class ShardSelector(unittest.TestCase):
    """MERGE_SHARD=<i>/<n> splits a selection into n disjoint shards that together hold every test."""
    def all_tests(self):
        return unittest.defaultTestLoader.loadTestsFromModule(sys.modules[__name__])

    def ids(self, suite):
        return [t.id() for t in iter_tests(suite)]

    def test_the_shards_are_disjoint_and_hold_every_test(self):
        for base in (self.all_tests, lambda: select_tests(self.all_tests(), "windows-slice")):
            full = self.ids(base())
            for n in (1, 2, 3, 4):
                shards = [self.ids(select_shard(base(), f"{i}/{n}")) for i in range(1, n + 1)]
                self.assertEqual(sorted(sum(shards, [])), sorted(full), n)
                self.assertTrue(all(abs(len(a) - len(b)) <= 1 for a in shards for b in shards), n)

    def test_no_value_keeps_every_test(self):
        self.assertEqual(self.ids(select_shard(self.all_tests(), "")), self.ids(self.all_tests()))

    def test_a_bad_value_fails_loudly_and_runs_nothing(self):
        for bad in ("0/2", "3/2", "1", "1/0", "a/b", "1/2/3"):
            with self.assertRaises(SystemExit) as cm:
                select_shard(self.all_tests(), bad)
            self.assertIn("MERGE_SHARD", str(cm.exception))
        r = subprocess.run([sys.executable, os.path.abspath(__file__)], capture_output=True, text=True,
                           env=dict(os.environ, MERGE_SHARD="2/1"), timeout=60)
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("MERGE_SHARD", r.stdout + r.stderr)
        self.assertNotIn("Ran ", r.stdout + r.stderr)

def workflow_text(name, *jobs):
    """A workflow file whose top-level name is `name`, with one job per id in `jobs`, one step each."""
    lines = [f"name: {name}", "on: push", "jobs:"]
    for job in jobs:
        lines += [f"  {job}:", "    runs-on: ubuntu-latest", "    steps:", "      - run: echo ok"]
    return "\n".join(lines) + "\n"


class SilentWait(Env):
    """Silence: merge printed only the launch line for minutes. A long step printed
    nothing before it started. A `gh` call whose helper keeps its stdout open also blocks silently (measured:
    subprocess.run waits for the pipe, not the child). Each case holds one call that way and checks that merge
    prints a line before the call blocks. Not a GhHalf subclass: the GhHalf tests must not run twice."""
    set, calls, gh_host, go = GhHalf.set, GhHalf.calls, GhHalf.gh_host, GhHalf.go

    def setUp(self):  # the fake-gh setup of GhHalf.setUp, without its tests
        Env.setUp(self)
        install_gh_shim(self)
        self.ticks, self.paused, self.at_pause = 0, [], []
        self.set(checks_seq=[[("checks", "pass", "")]])

    def hold_run(self, on, seconds, host):
        """Run the merge in a thread, hold the first `on` call, and read stdout while it is held.
        -> (text printed while held, rc or the thread's error, text printed in all)."""
        out, err, result = io.StringIO(), io.StringIO(), {}
        self.set(hold={"on": on, "seconds": seconds})

        def go():
            try:
                with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                    first = merge.main(["7", "--confirm"], host=host, lock=self.lock)  # the claim step: pushes the claim and stops
                    claimed = claim_pushed_line(out.getvalue() + err.getvalue())
                    result["rc"] = merge.main(["7", "--confirm"], host=host, lock=self.lock) if first == 0 and claimed else first  # the merge step
            except BaseException as e:  # a crash in the thread must fail the test, not vanish
                result["error"] = repr(e)

        cwd = os.getcwd()
        os.chdir(self.co)
        try:
            t = threading.Thread(target=go, daemon=True)
            t.start()
            marker = os.path.join(self.state, "held")
            stop = time.time() + 60
            while not os.path.exists(marker) and time.time() < stop:
                time.sleep(0.05)
            self.assertTrue(os.path.exists(marker), "the held call never started")
            time.sleep(4)  # a human watching the terminal gets this long before anything is said
            seen = out.getvalue()
            t.join(seconds + 60)
            self.assertFalse(t.is_alive(), "the merge did not end")
        finally:
            os.chdir(cwd)
        return seen, result.get("rc", result.get("error")), out.getvalue() + err.getvalue()

    def assert_names_the_held_step(self, seen, step):
        """The last line printed while the call was held must say merge is waiting or doing that step. A claim's
        `pushed` line is not that: it says what happened, not what merge is blocked on."""
        last = seen.splitlines()[-1] if seen.strip() else ""
        self.assertRegex(last, r"(?i)waiting|checking|merging", f"while `{step}` was held the last line was {last!r}; printed so far: {seen!r}")

    def test_a_held_check_read_names_its_step_before_it_blocks(self):
        seen, _, _ = self.hold_run("check-runs", 12, self.gh_host())
        self.assert_names_the_held_step(seen, "the check runs read")

    def test_a_held_merge_call_names_its_step_before_it_blocks(self):
        seen, rc, out = self.hold_run("merge", 12, self.gh_host())
        self.assertEqual(rc, 0, out)
        self.assert_names_the_held_step(seen, "the merge call")

    def test_red_required_check_beside_skipped_jobs_refuses_at_once(self):
        self.set(checks_seq=[[("checks", "fail", "https://x/checks"), ("scope", "skipping", ""), ("check-windows", "skipping", "")]],
                 runs_seq=[[("checks", "completed", "failure"), ("check-windows", "completed", "skipped")]])
        rc, out = self.go(required=("checks", "scope"))
        self.assertEqual(rc, 1, out)
        self.assertIn("a check is red", out)
        self.assertEqual(self.paused, [], "a red head waited before it refused")
        self.assertNotIn(MERGE_CALL, self.calls())

    def test_zero_contexts_and_a_required_name_with_no_run_say_what_they_wait_on(self):
        self.set(checks_seq=[[]], runs_seq=[[("check", "in_progress", None)]])
        rc, out = self.go(required=("check",))
        self.assertEqual(rc, 1, out)
        self.assertIn("a check is pending: check", out)  # the refusal names the required check it found pending; the run's own line was the wait's

_real_threading = threading  # the real module. merge's `threading` name is swapped in the scan cases, this name is not

class TickEvent:
    """Stands in for threading.Event in merge.undo_check. wait() returns only when a test releases a tick,
    so the heartbeat thread runs when the test says so. set() ends it, as a real Event does."""
    def __init__(self):
        self.flag, self.ticks = _real_threading.Event(), _real_threading.Semaphore(0)

    def wait(self, timeout=None):
        self.ticks.acquire()
        return self.flag.is_set()

    def set(self):
        self.flag.set()
        self.ticks.release()

    def is_set(self):
        return self.flag.is_set()

    def tick(self):
        self.ticks.release()

class QuickEvent(_real_threading.Event):
    """A real Event whose wait() ignores its timeout and waits 20 ms: the heartbeat's 60 s pass, made tiny."""
    def wait(self, timeout=None):
        return super().wait(0.02)

class FakeThreading:
    """merge's `threading` name for one undo_check call. Event is the test's stand-in. Thread is the real class,
    and every thread it makes is kept, so the test can join it. Any other name is the real module's."""
    def __init__(self, event_cls):
        self.Event, self.threads = event_cls, []

    def Thread(self, *a, **k):
        t = _real_threading.Thread(*a, **k)
        self.threads.append(t)
        return t

    def __getattr__(self, name):
        return getattr(_real_threading, name)

class ScanProgress(Env):
    """The silent-undo scan (lint/check_silent_undo.py) can run for 14 minutes on a long branch. merge.undo_check
    printed nothing until it ended. It must print a start line with the size of the scan, and an end line.
    The scanner is replaced by a stub here: the cases test merge's lines around the call, not the scan."""

    def run_undo(self):
        """-> (text printed before the scanner was called, text printed in all)."""
        out, seen = io.StringIO(), []
        stub = unittest.mock.MagicMock()

        def scan(cwd, upstream, head, default=None, tool=None, pr_body="", run_state=None, retire_head=None):
            seen.append(out.getvalue())
            return [], []

        stub.check.side_effect = scan
        with unittest.mock.patch.dict(sys.modules, {"check_silent_undo": stub}), contextlib.redirect_stdout(out):
            merge.undo_check(self.co, "origin/main")
        return seen[0], out.getvalue()

    def test_a_start_line_with_the_size_comes_before_the_scan(self):
        before, _ = self.run_undo()
        self.assertRegex(before, r"(?m)^merge: scanning for silent undos \(\d+ commits?", f"printed before the scan: {before!r}")

    def test_the_scan_says_when_it_ends(self):
        _, after = self.run_undo()
        self.assertRegex(after, r"(?m)^merge: silent-undo scan done", f"printed after the scan: {after!r}")

    def stub(self, check=None):
        """A stand-in for lint/check_silent_undo: no finding, no progress hook, and a real Unknown class, so an
        error that is not Unknown reaches merge's finally, not a TypeError in its except clause."""
        s = unittest.mock.MagicMock()
        s.progress, s.Unknown = None, type("Unknown", (Exception,), {})
        s.check.side_effect = check if check is not None else (lambda *a, **k: ([], []))
        return s

    def run_undo_scan(self, stub, event_cls=None, on_line=None):
        """Run merge.undo_check on the test checkout with `stub` as the scanner. event_cls swaps in merge's
        threading.Event. on_line(line, from_main_thread) sees each line merge prints, after it prints. -> the printed text."""
        out, real_say = io.StringIO(), merge.say

        def say(*lines):
            real_say(*lines)
            for line in lines:
                if on_line:
                    on_line(line, _real_threading.current_thread() is _real_threading.main_thread())

        fake = FakeThreading(event_cls or _real_threading.Event)
        with unittest.mock.patch.dict(sys.modules, {"check_silent_undo": stub}), unittest.mock.patch.object(merge, "threading", fake), \
                unittest.mock.patch.object(merge, "say", say), contextlib.redirect_stdout(out):
            try:
                merge.undo_check(self.co, "origin/main")
            finally:
                for t in fake.threads:
                    t.join(1)
        return out.getvalue()

    def test_no_heartbeat_prints_after_the_scan_is_done(self):
        """The race: a beat is due as the scan ends. The done line prints first. Then a tick lets the beat's wait
        return, and the beat prints, before done.set() runs. The done line's hook holds merge until that beat has printed."""
        made, beat_printed = [], _real_threading.Event()

        def make_event():
            made.append(TickEvent())
            return made[-1]

        def on_line(line, from_main):
            if from_main and line.startswith("merge: silent-undo scan done"):
                made[0].tick()
                beat_printed.wait(0.5)
            elif not from_main:
                beat_printed.set()

        out = self.run_undo_scan(self.stub(), event_cls=make_event, on_line=on_line)
        lines = out.splitlines()
        done = [i for i, line in enumerate(lines) if line.startswith("merge: silent-undo scan done")]
        self.assertTrue(done, f"no done line printed: {out!r}")
        self.assertEqual(done[-1], len(lines) - 1, f"printed after the scan was done: {lines[done[-1] + 1:]}")

    def test_a_scan_that_outlasts_the_interval_prints_a_beat_before_it_ends(self):
        """A 20 ms beat (QuickEvent) and a scan that holds until a beat prints, for up to 1 s."""
        beat_printed, during = _real_threading.Event(), []

        def on_line(line, from_main):
            if not from_main and line.startswith("merge: silent-undo scan:"):
                beat_printed.set()

        def check(*a, **k):
            during.append(beat_printed.wait(1))
            return [], []

        out = self.run_undo_scan(self.stub(check), event_cls=QuickEvent, on_line=on_line)
        self.assertEqual(during, [True], f"no beat printed during the scan: {out!r}")

    def test_the_progress_hook_is_cleared_after_a_scan_and_when_the_scan_raises(self):
        # Rows: the scan returns (no check error); the scan raises. Either way the hook must not stay set.
        for check in (None, RuntimeError("scan broke")):
            with self.subTest(scan="raises" if check else "returns"):
                merge.UNDO_MEMO.clear()  # a memo hit skips the scan, so the second row must start empty
                stub = self.stub(check)
                if check is None:
                    self.run_undo_scan(stub)
                else:
                    with self.assertRaises(RuntimeError):
                        self.run_undo_scan(stub)
                self.assertIsNone(stub.progress, "the progress hook stayed set after the scan")

class WaitStepLines(unittest.TestCase):
    """Each long step prints its name before its first gh call can block: the check read and the merge call.
    A probe stands in for `gh`. It snapshots stdout at the first call, then raises. No shim, no git repo."""
    class Probe(Exception):
        pass

    def first_call_text(self, host, step):
        """-> the stdout printed before the first gh call that `step` makes."""
        out, seen = io.StringIO(), []

        def gh(args, cwd=None):
            seen.append(out.getvalue())
            raise self.Probe(args)

        host.gh = gh
        with contextlib.redirect_stdout(out), self.assertRaises(self.Probe):
            step(host)
        self.assertTrue(seen, "no gh call was made")
        return seen[0]

    def test_the_merge_step_is_named_before_the_merge_call(self):
        host = merge.Host(required=["checks"], base="main", minute=60, now=lambda: 0.0, pause=lambda s: None)
        before = self.first_call_text(host, lambda h: h.merge(7, "merge", "sha"))
        self.assertRegex(before, r"(?m)^merge: merging #7", f"printed before the merge call: {before!r}")

# ---- the records page is rebuilt at merge time --------------------------------------------------------------------

# The records-only mode of lint/hook_catalog.py: it writes docs/records.md and nothing else. The merge
# tool passes it with --root on every run, so a root with catalog parts gets no docs/catalog.md in its merge commit.
RECORDS_ONLY = "--records-only"

FAKE_RECORDS = '''import json, os, sys
a = sys.argv[1:]
root = a[a.index("--root") + 1]
with open(os.environ["RECORDS_CALLS"], "a") as f:
    f.write(json.dumps(a) + "\\n")
mode = os.environ.get("RECORDS_MODE", "")  # set by RecordsEnv.generator_mode, for one run
if mode == "fail":
    print("records: the generator failed")
    sys.exit(1)
if mode == "silent":
    sys.exit(0)  # writes nothing, so the tree is the same after the run
if os.path.exists(os.path.join(root, "debts", "bad.md")):
    print("records: debts/bad.md has no What")
    sys.exit(1)
d = os.path.join(root, "debts")
names = sorted(n[:-3] for n in os.listdir(d)) if os.path.isdir(d) else []
os.makedirs(os.path.join(root, "docs"), exist_ok=True)
with open(os.path.join(root, "docs", "records.md"), "w", newline="\\n") as f:
    f.write("records\\n" + "".join("- %s\\n" % n for n in names))
'''
DEBT_TEXT = "# Gap one\n\n- **What.** The check misses one case.\n- **Where.** x\n- **Decision.** none\n- **Retire.** y\n"

def page(*names):
    """The page the fake generator writes for these debts."""
    return "records\n" + "".join("- %s\n" % n for n in names)

def put_lf(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", newline="\n") as f:
        f.write(text)

class RecordsEnv(Env):
    """Helpers for the records-page cases. Holds no test."""
    def use_fake_records(self):
        """Patch merge.RECORDS to the fake generator (FAKE_RECORDS) for this case. Sets self.calls (its log) and self.prog."""
        self.calls, self.prog = os.path.join(self.t, "records-calls.log"), os.path.join(self.t, "records.py")
        put(self.prog, FAKE_RECORDS)
        for p in (unittest.mock.patch.object(merge, "RECORDS", self.prog, create=True),  # create: a missing name is a failure, not an error
                  unittest.mock.patch.dict(os.environ, {"RECORDS_CALLS": self.calls})):
            p.start(); self.addCleanup(p.stop)

    def generator_mode(self, mode):
        """Run the fake generator in `mode` for as long as the returned context lasts: "fail" exits 1, "silent" writes nothing (FAKE_RECORDS reads RECORDS_MODE)."""
        return unittest.mock.patch.dict(os.environ, {"RECORDS_MODE": mode})

    def generator_runs(self):
        """-> how many times the fake generator has run in this case: its call log has one line a run."""
        if not os.path.exists(self.calls):
            return 0
        with open(self.calls) as f:
            return sum(1 for _ in f)

    def tool_page(self, parent, changes=None, hand="", rebuild=True):
        """-> the sha of the commit the merge tool writes for a records-page rebuild on `parent`. The tool's own rebuild and commit run in a worktree
        of this run's folder. `changes` are written before the rebuild, so they join the commit. `hand` is text added to the page after the rebuild.
        `rebuild=False` makes a page the tool did not write: the page is `hand` alone, or removed when `hand` is None."""
        wt = os.path.join(self.t, "page-wt")
        sh(self.co, "git", "worktree", "add", "-q", "--detach", wt, parent)
        try:
            page_path = os.path.join(wt, *merge.RECORDS_PAGE.split("/"))
            for path, text in (changes or {}).items():
                put_lf(os.path.join(wt, *path.split("/")), text)
            if rebuild:
                merge.rebuild_records(wt)
                if hand:
                    with open(page_path, "a", newline="\n") as f:
                        f.write(hand)
            elif hand is None:
                os.remove(page_path)
            else:
                put_lf(page_path, hand)
            return merge.commit_claim(wt, None)
        finally:
            sh(self.co, "git", "worktree", "remove", "--force", wt)

    def assert_page_scope(self, sha, parent, files=None):
        """Scope before subject (P7): the walk from `parent` to `sha` is `sha` alone, `sha` has one parent, its subject is PAGE_SUBJECT, and the
        files it changes are `files` (the records page by default)."""
        self.assertEqual(sh(self.co, "git", "rev-list", f"{parent}..{sha}").split(), [sha], "fixture: the walk from the parent to the page commit is not that commit alone")
        self.assertEqual(sh(self.co, "git", "rev-list", "--parents", "-n", "1", sha).split()[1:], [parent], "fixture: the page commit does not have one parent")
        self.assertEqual(sh(self.co, "git", "log", "-1", "--format=%s", sha), merge.PAGE_SUBJECT, "fixture: the page commit's subject is not PAGE_SUBJECT")
        changed = sh(self.co, "git", "diff-tree", "--no-commit-id", "--name-only", "-r", sha).split()
        self.assertEqual(sorted(changed), sorted(files or [merge.RECORDS_PAGE]), "fixture: the page commit changes other files than it should")

    def kinds_off(self):
        """The base holds claude-settings' own config: no stamp kinds, so no claim."""
        self.on("main", {".github/stamp.json": json.dumps(dict(CONFIG, kinds=[]))}, "no stamp kinds")
        sh(self.co, "git", "pull", "-q", "--ff-only")
        head_takes_base(self)

    def on(self, branch, files, msg="records"):
        """Push one commit to origin/<branch> from the second clone, as a person or another run would."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", branch, f"origin/{branch}")
        for rel, text in files.items():
            put_lf(os.path.join(o, rel), text)
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", msg); sh(o, "git", "push", "-q", "origin", branch)

    def main_debt_conflicts(self):
        """main adds the debt the head adds, with other text: the merge of the head and main conflicts on it. Under rule M3 a clean base
        move stands, so a case that needs a refused head moves main this way."""
        self.on("main", {"debts/gap-one.md": DEBT_TEXT.replace("Gap one", "Main gap")}, "untooled push")

    def drop(self, branch, rel, msg):
        """Push one commit to origin/<branch> from the second clone that removes rel, as a person would."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", branch, f"origin/{branch}")
        sh(o, "git", "rm", "-q", rel); sh(o, "git", "commit", "-qm", msg); sh(o, "git", "push", "-q", "origin", branch)

    def draft_confirm(self, lock=None):
        """--confirm on the pull request while it is a draft: the records step, then the mark-ready call. Never a merge."""
        self.host.draft = True  # a draft, whatever the last step left
        return self.run_merge("7", "--confirm", lock=lock)

    def preview_line(self, out, label):
        """The one preview line that starts `  <label>:`."""
        lines = [l for l in out.splitlines() if l.startswith(f"  {label}:")]
        self.assertEqual(len(lines), 1, out)
        return lines[0]

    def draft_preview(self):
        """The preview of the pull request while it is a draft. -> its output. Presses nothing."""
        self.host.draft = True
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        return out

    def claim_head(self, files=None):
        """Push a head that holds a Record-claim for D-002 under the default config, with files added. The ready confirm resumes
        that claim, so a stale page on it is pushed as a page commit: the resumed path, which a refusal never reaches."""
        files = dict(files or {})
        files["docs/decisions/second.md"] = record("D-002", "second")
        self.on("feat", files, "Claim record numbers\n\nRecord-claim: D-002")

    def assert_remedy(self, text):
        """The remedy in order: back to draft, `merge 7 --confirm` on the draft, then ready."""
        self.assertRegex(text, r"draft[\s\S]*merge 7 --confirm[\s\S]*ready", text)

    def assert_revert_remedy(self, text):
        """The remedy for a head that holds a Record-claim on a base that stamps nothing for it: revert that claim commit,
        then the records step on the draft. The draft step refuses a claim head, so `merge 7 --confirm` is never named before the revert."""
        self.assertRegex(text, r"holds a Record-claim", text)
        self.assertRegex(text, r"[Rr]evert[^.]*claim", text)
        revert = re.search(r"[Rr]evert", text)
        before, after = text[:revert.start()], text[revert.start():]
        self.assertNotIn("merge 7 --confirm", before, text)
        self.assertIn("records step", after, text)
        self.assertIn("draft", after, text)

    def assert_refused_on_ready(self, rc, out, refs_before):
        """A ready pull request with a stale page and nothing to claim or resume: refused before any check wait, with nothing
        pushed, claimed or merged, the lock freed and the worktree dropped. The remedy is back to draft."""
        self.assert_refused_untouched(rc, out, refs_before)
        self.assert_remedy(out)

    def assert_refused_untouched(self, rc, out, refs_before):
        """A refusal before any check wait: nothing pushed, claimed or merged, the lock freed and the worktree dropped."""
        self.assertEqual(rc, 1, out)
        self.assertEqual(self.refs(), refs_before, "pushed or claimed on a refusal")
        self.assertEqual(self.host.waits, [], "waited on checks before refusing")
        self.assertFalse(getattr(self.host, "merged", False), out)
        self.assertFalse(self.lock_ref(), "the lock was not released")
        self.assertEqual(self.worktrees(), 1, "the worktree was not dropped")

    def spy_merge(self):
        """Replace the host's merge with a recorder. -> the list of shas it was asked to merge."""
        asked = []
        def merge_call(n, method, sha):
            asked.append(sha)
            return None, "spy: a draft confirm must not merge"
        self.host.merge = merge_call
        return asked

    def reject_pushes(self, branch):
        """A pre-receive hook on origin that refuses any push to branch, as a branch rule would."""
        put_lf(os.path.join(self.bare, "hooks", "pre-receive"),
               "#!/bin/sh\nstatus=0\nwhile read old new ref; do\n"
               f"  if [ \"$ref\" = \"refs/heads/{branch}\" ]; then\n    echo \"pre-receive: refused $ref\" >&2\n    status=1\n  fi\n"
               "done\nexit $status\n")
        os.chmod(os.path.join(self.bare, "hooks", "pre-receive"), 0o755)

def claim_pushed_line(out):
    """The stop line of a two-step confirm: the one line that says the claim is pushed and to confirm again. '' when there is none."""
    return next((l for l in out.splitlines() if "claim" in l and "pushed" in l and "confirm" in l), "")

class TwoStepConfirm(RecordsEnv):
    """Two-step confirm. A claim is a commit on the pull request head, and the claim head's own checks must run before it merges. So a confirm
    that must push its claim commit pushes it and stops: no merge call, no wait, and one stop line that says the claim is pushed and to confirm
    again. The next confirm, on the claim head, merges it. A confirm that needs no claim merges in one run. Each case names its cause in its first assert."""

    def test_the_first_confirm_calls_no_merge_put(self):
        asked = []
        real_merge = self.host.merge
        def spy(n, method, sha):
            asked.append(sha)
            return real_merge(n, method, sha)
        self.host.merge = spy
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(asked, [], "the first confirm called the merge PUT, so it did not stop at the claim: %s" % out)

    def test_the_first_confirm_stops_with_a_line_that_says_the_claim_is_pushed(self):
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(claim_pushed_line(out), "no stop line says the claim is pushed and to confirm again: %s" % out)

    def test_the_first_confirm_leaves_its_claim_commit_on_the_lane_head(self):
        before = self.head("feat")
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertFalse(getattr(self.host, "merged", False), "the first confirm merged, so the lane head is gone: %s" % out)  # scope first
        claim = self.head("feat")
        self.assertNotEqual(claim, before, "the first confirm pushed no claim commit: %s" % out)
        sh(self.co, "git", "fetch", "-q", "origin")
        self.assertEqual(sh(self.co, "git", "log", "-1", "--format=%s", claim), "Claim record numbers", "the lane head is not the claim commit")

    def test_a_confirm_that_needs_no_claim_merges_in_one_run(self):
        self.leave_no_pending_record()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), "a confirm with nothing to claim did not merge in one run: %s" % out)

    def test_the_second_confirm_merges_the_claim_head(self):
        relayed = self.head("feat")
        self.claim_head()  # the claim commit the first confirm pushes, on the relayed head
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), "the second confirm did not merge the claim head: %s" % out)

    def test_the_second_confirm_on_a_pending_claim_head_refuses_before_any_push(self):
        relayed = self.head("feat")
        self.claim_head()
        self.host.state = "pending: checks: running"  # the claim head's required check has not reported
        self.host.checks = (None, "a required check is pending")
        before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 1, out)
        self.assertEqual(self.refs(), before, "a push landed on a claim head whose check is pending")
        self.assertFalse(getattr(self.host, "merged", False), out)

    def test_the_second_confirm_on_a_red_claim_head_refuses(self):
        relayed = self.head("feat")
        self.claim_head()
        self.host.state = "red: checks: fail"  # the claim head's required check is red
        self.host.checks = (False, "a check is red: checks: fail")
        before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 1, out)
        self.assertEqual(self.refs(), before, "a push landed on a claim head whose check is red")
        self.assertFalse(getattr(self.host, "merged", False), out)

    def test_the_relayed_yes_binds_across_the_claim_commit(self):
        relayed = self.head("feat")
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertFalse(getattr(self.host, "merged", False), "the first confirm merged instead of stopping at the claim: %s" % out)
        self.assertTrue(claim_pushed_line(out), "no stop line after the claim push: %s" % out)
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)  # the relayed head is the parent of the claim commit
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), "the relayed yes did not carry over the claim commit: %s" % out)

    def test_a_rival_commit_on_the_claim_head_refuses_the_relayed_yes(self):
        relayed = self.head("feat")
        self.claim_head()  # the claim commit on the relayed head
        self.competitor_push()  # a rival commit lands on top of the claim: the relayed head is no longer the parent of the live head
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 1, out)
        self.assertIn("moved", out, "the refusal does not say the head moved: %s" % out)
        self.assertFalse(getattr(self.host, "merged", False), out)

    def test_a_relayed_yes_survives_a_page_only_rebuild_commit_on_the_claim_head(self):
        relayed = self.head("feat")
        self.claim_head()  # the claim commit the first confirm pushes, on the relayed head
        self.on("feat", {merge.RECORDS_PAGE: page()}, "Rebuild the records page")  # the resumed page commit: the records page alone, no trailer
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertNotIn("so that yes does not cover it", out, "the relayed yes was refused for a page-only rebuild commit: %s" % out)  # scope first: not refused as moved
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), "the relayed yes did not carry over the page-only rebuild commit: %s" % out)

    def test_a_commit_with_the_page_subject_but_another_file_still_refuses_the_relayed_yes(self):  # control: green on the old code
        relayed = self.head("feat")
        self.claim_head()
        self.on("feat", {"rival.txt": "someone else pushed\n"}, "Rebuild the records page")  # the subject alone does not make a page commit
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 1, out)
        self.assertIn("so that yes does not cover it", out, "the refusal does not say the relayed yes is not covered: %s" % out)
        self.assertFalse(getattr(self.host, "merged", False), out)

class ClaimCollision(RecordsEnv):
    """Two lanes claim the same record number between their confirms (per-lane merge, the coordinator's pick of Nov 12 2026). Lane B's first
    confirm pushes its claim D-002 and stops. Lane A then merges, and main holds D-002. Lane B's second confirm finds its own claim taken on main:
    it reverts that claim while its branch still holds it, says so, and stops. Its next confirm claims a fresh number and merges. Lane A's merge
    is a push of its record to main from the second clone, as a landed merge leaves it. Each case names its cause in its first assert."""

    def setUp(self):
        super().setUp()
        self.use_fake_records()

    def lane_b_pushes_its_claim(self):
        """Lane B's first confirm: it pushes its claim commit and stops. -> the sha of that claim head."""
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(claim_pushed_line(out), "lane B's first confirm did not stop at its pushed claim: %s" % out)
        return self.head("feat")

    def lane_a_merges(self):
        """Lane A's merge lands on main: its record holds D-002 and carries the claim trailer."""
        self.on("main", {"docs/decisions/lane-a.md": record("D-002", "lane-a")}, "Claim record numbers\n\nRecord-claim: D-002")

    def test_a_second_confirm_whose_claim_main_holds_reverts_it_and_stops(self):
        claim = self.lane_b_pushes_its_claim()
        self.lane_a_merges()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 1, out)  # scope first: the confirm stops
        self.assertFalse(getattr(self.host, "merged", False), "lane B merged on a claim main already holds: %s" % out)
        self.assertNotEqual(self.head("feat"), claim, "lane B kept the claim D-002 that main holds: %s" % out)
        self.assertEqual(self.log1("%s", "origin/feat"), 'Revert "Claim record numbers"', "feat's head is not the revert of the claim: %s" % out)
        self.assertRegex(out, r"[Rr]evert", "the stop does not name the revert: %s" % out)
        self.assertRegex(out, r"--confirm", "the stop does not name the next confirm: %s" % out)

    def test_the_lane_whose_claim_collided_claims_a_fresh_number_and_merges(self):
        self.lane_b_pushes_its_claim()
        self.lane_a_merges()
        self.run_merge_once("7", "--confirm")  # the revert stop
        rc, out = self.run_merge("7", "--confirm")  # the next confirm claims, pushes, and merges on its second step
        self.assertEqual(rc, 0, "the confirm after the revert did not merge: %s" % out)
        self.assertTrue(getattr(self.host, "merged", False), "the confirm after the revert did not merge: %s" % out)
        self.assertEqual(self.log1("%(trailers:key=Record-claim,valueonly)", "origin/main^2").strip(), "D-003",
                         "the merged claim is not the fresh number D-003: %s" % out)

    def test_a_second_confirm_whose_claim_main_does_not_hold_still_merges(self):  # control: green on the old code
        self.lane_b_pushes_its_claim()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), "a claim main does not hold did not merge on its second confirm: %s" % out)
        self.assertEqual(self.log1("%(trailers:key=Record-claim,valueonly)", "origin/main^2").strip(), "D-002")

class ResumedPageStale(RecordsEnv):
    """A resumed claim whose records page is current on its own tree, but stale for the merge with main. Confirm proves the merge result after
    its claim is on origin, and a stale proof stops the run. This run pushed nothing (the claim is the lane's, already on origin), so the
    refusal reverts nothing: a revert push would undo a claim this run did not make, and the refusal's words say nothing was pushed."""

    def setUp(self):
        super().setUp()
        self.use_fake_records()

    def test_a_resumed_claim_whose_page_main_makes_stale_is_refused_with_no_push(self):
        self.claim_head({"docs/records.md": page()})  # the claim, and a page current on the head's own tree
        self.on("main", {"debts/gap-two.md": DEBT_TEXT.replace("Gap one", "Main gap")}, "a debt lands on main")  # the merge result would change the page
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 1, out)  # scope first: the run refuses
        self.assertFalse(getattr(self.host, "merged", False), "the stale page was merged: %s" % out)
        self.assertEqual(self.refs(), refs_before, "a push landed on the page-stale refusal, which says nothing was pushed: %s" % out)
        self.assertIn("Nothing was merged or pushed", out)

class RecordsRebuild(RecordsEnv):
    """The records index is rebuilt at merge time, the way record numbers are claimed
    from the slug form at merge: merge.py runs a records generator.

    The contract for merge/merge.py. The seam is confirm() and preview(), beside do_claim and commit_claim.
    - One home: `merge.RECORDS`, the path of lint/hook_catalog.py beside merge/ in the same checkout, as `merge.STAMP` is
      for the stamp engine. The tool brings the generator, so a repo adds no config and no script. These cases patch it.
    - Run `python3 <RECORDS> --root <worktree>`, nothing else, in the detached worktree that holds the head: the tree
      that merges, never the caller's checkout. A non-zero exit is one Stop line starting "merge: " that names the
      generator's reason once. Nothing is pushed, and the lock is freed.
    - When: after the claim, only when the pull request's base is the default branch (the claim's own rule). The rebuild
      runs with or without stamp kinds (claude-settings itself has `kinds: []`).
    - A stale page on a ready pull request with no claim to make or resume is refused before any wait. Nothing is pushed
      or claimed, the lock is freed, and the refusal names the remedy: back to draft, `merge <n> --confirm` on the draft,
      then ready. The draft step is where a stale page heals. A head that holds a Record-claim on a base with no stamp
      kinds is refused the same way, but its remedy is the revert of that claim commit, then the records step on the draft:
      the draft step refuses a claim head, so it is never named first. The preview's records line gives the same remedy.
    - The claim and the rebuild share one commit. With a claim: "Claim record numbers", with its Record-claim trailer, and
      the page in the same commit. A resumed claim with a stale page: the subject "Rebuild the records page", and no
      Record-claim trailer. The head is read green once, before the page commit is pushed; nothing waits on the new sha.
    - Nothing changed in the worktree: no commit, and no wait.
    - Proof before the merge call: after the last fetch of the base, merge origin/<base> into the worktree without a
      commit and run the generator. When it would change the page, the page on the head is stale for the merge result
      (the base moved with a record): refuse with a line that says "records page" and "stale", revert the rebuild
      commit, merge nothing. A base that moved with an unrelated change merges. The lock keeps other tool merges out,
      so only a push that did not use the tool can trip it.
    - The preview prints one line `  records: rebuild ...` or `  records: current`, and presses nothing. A ready pull request
      refused as above: the same line says `--confirm refuses it` and gives the remedy.
    - A draft pull request: `--confirm` is the records step. It refuses a head that does not hold the base tip (the line
      says BEHIND), commits the page alone when it is stale and pushes it, then marks the pull request ready and stops.
      It never merges, takes no merge lock and claims no record number. A current page adds no commit. A refused push
      stops before the mark-ready call. If the mark-ready call fails, one line tells the reader to mark it ready, the
      push stays, and the exit is 0. A ready confirm then finds the page current, pushes nothing, and merges the sha the
      draft step pushed.
    - Under merge.requiredChecks "none" (decision private-repos-no-ci) a ready confirm heals the page itself, in one run and with no
      wait: a page-only commit on the head, or main merged in first when main gained a record, then the merge of that head. A base that
      moves after the heal's push refuses and keeps the pushed commit. The refusals above stay for a named list and for "protection".

    Ruling: records-index-at-merge (confirm on a draft is the records page step)
    """
    def setUp(self):
        super().setUp()
        self.use_fake_records()

    def set_required(self, required):
        """Commit the base's config with merge.requiredChecks `required`, and give the fake host the same value: production sets the host's
        value from this config (root_host), so a case states it once and both places read it."""
        put_base_config(self, json.dumps(dict(CONFIG, merge=dict(CONFIG["merge"], requiredChecks=required))))
        self.assertEqual(json.loads(self.show("main", ".github/stamp.json"))["merge"]["requiredChecks"], required, "fixture: the base does not name " + repr(required))
        self.host.required = required

    def drop_pending_record(self):
        """The head holds no pending record, so a confirm claims no number and the page is its only change to make."""
        self.drop("feat", "docs/decisions/second.md", "drop the pending decision")

    def main_gains_a_record_under_none(self):
        """Under none: the head's own page is current, and main gains a record the head lacks. -> (main's tip, the head) before the run."""
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})  # current for the head's own debts: none
        self.on("main", {"debts/gap-one.md": DEBT_TEXT}, "untooled push")  # a record the head lacks
        return self.head("main"), self.head()

    def merge_and_page_pushed_on(self):
        """Push onto the head what `merge --ready` pushes on a head that lacks the base tip: the base merged in, then the page rebuilt on
        that merge. The merge goes up from the other clone; the page is built in the tool's own checkout (tool_page). -> the page commit."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(o, "git", "merge", "-q", "--no-ff", "--no-edit", "origin/main")
        sh(o, "git", "push", "-q", "origin", "feat")
        merged = sh(o, "git", "rev-parse", "HEAD")
        sh(self.co, "git", "fetch", "-q", "origin")
        page_sha = self.tool_page(merged)
        sh(self.co, "git", "push", "-q", "origin", f"{page_sha}:refs/heads/feat")
        return page_sha

    def base_merge_pushed_on(self, source, edit=None):
        """Push onto the head a merge of `source` (a ref of the second clone), as a person makes one. `edit` ({path: text}) is written into the merge
        before it is committed, so the merge's tree may differ from git's clean merge. -> the merge sha."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(o, "git", "merge", "-q", "--no-ff", "--no-commit", source)
        for path, text in (edit or {}).items():
            put_lf(os.path.join(o, path), text)
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "Merge " + source); sh(o, "git", "push", "-q", "origin", "feat")
        return sh(o, "git", "rev-parse", "HEAD")

    def clean_merge_tree(self, first, second):
        """-> the tree id of git's clean merge of two commits, or None when they conflict."""
        r = subprocess.run(["git", "merge-tree", "--write-tree", "--no-messages", first, second], cwd=self.co, capture_output=True, text=True)
        return r.stdout.split()[0] if r.returncode == 0 else None

    def assert_merge_shape(self, live, first, second, clean):
        """Scope before subject (P7): `live` is a merge of `first` then `second`. Its tree is git's clean merge of the two when `clean`, and is not when not."""
        sh(self.co, "git", "fetch", "-q", "origin")
        self.assertEqual(sh(self.co, "git", "rev-list", "--parents", "-n", "1", live).split()[1:], [first, second],
                         "fixture: the head is not a merge of the relayed head and the second parent")
        merged = self.clean_merge_tree(first, second)
        self.assertIsNotNone(merged, "fixture: git cannot merge the two parents cleanly")
        tree = sh(self.co, "git", "rev-parse", f"{live}^{{tree}}")
        if clean:
            self.assertEqual(tree, merged, "fixture: the merge's tree is not git's clean merge")
        else:
            self.assertNotEqual(tree, merged, "fixture: the merge's tree is git's clean merge, so the edit did not change it")

    def assert_healed_merge(self, out, main_tip, head):
        """The one confirm merged the head: the merge's second parent holds the base tip and the head the run started from, main's page is
        current, and the run claimed no number and waited on no check."""
        self.assertTrue(getattr(self.host, "merged", False), out)
        healed = self.rev("origin/main^2")  # deleteBranch removes feat, so the merge's second parent is the pushed head
        ancestors = sh(self.co, "git", "rev-list", healed).split()
        self.assertIn(main_tip, ancestors, "the merged head does not hold the base tip that the heal merged in")
        self.assertIn(head, ancestors, "the merged head does not hold the head the run started from")
        self.assertEqual(self.show("main", merge.RECORDS_PAGE), page("gap-one").strip(), "main's page is not current after the merge")
        self.assertEqual(self.claims(), 0, "claimed a number for a page heal")
        self.assertEqual(self.host.waits, [], "the one confirm waited on a check")

    def test_under_none_a_stale_own_page_heals_in_one_confirm_and_merges(self):
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})  # a page that names a debt nobody has
        before = self.head()
        rc, out = self.run_merge_once("7", "--confirm")  # one run: the case pins the single confirm, not the two-step claim stop
        self.assertEqual(rc, 0, "under none a stale own page did not heal in one confirm:\n" + out)
        healed = self.rev("origin/main^2")  # deleteBranch removes feat, so the merge's second parent is the page commit
        self.assert_page_scope(healed, before)
        self.assertEqual(self.show("main", merge.RECORDS_PAGE), page().strip())
        self.assertEqual(self.claims(), 0, "claimed a number for a page-only heal")
        self.assertEqual(self.host.waits, [], "the one confirm waited on a check")
        self.assertTrue(getattr(self.host, "merged", False), out)

    def test_under_none_a_base_that_gained_a_record_merges_main_in_and_heals_in_one_confirm(self):
        main_tip, before = self.main_gains_a_record_under_none()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, "under none a base that gained a record did not merge in one confirm:\n" + out)
        self.assert_healed_merge(out, main_tip, before)

    def test_under_none_a_stale_own_page_and_a_base_that_gained_a_record_heal_in_one_confirm(self):
        # Both heals at once: the head's own page is stale, and main gained a record. The refusal for the own page must not stand in the way.
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})  # a page that names a debt nobody has
        before = self.head()
        self.on("main", {"debts/gap-one.md": DEBT_TEXT}, "untooled push")
        main_tip = self.head("main")
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(rc, 0, "under none a stale own page and a base that gained a record did not heal in one confirm:\n" + out)
        self.assert_healed_merge(out, main_tip, before)

    def test_under_none_a_relayed_head_merges_across_the_merge_and_page_commits(self):
        # The heal's commits are already on the head, as `merge --ready` pushes them. The relayed yes names the head before them, so the
        # check must read a merge commit of the base as part of the relayed head (a head that moved in one run would pass it trivially).
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})
        before = self.head()  # the head the relayed yes names
        self.on("main", {"debts/gap-one.md": DEBT_TEXT}, "untooled push")
        main_tip = self.head("main")
        pushed = self.merge_and_page_pushed_on()
        self.assertNotEqual(self.head(), before, "scope: the live head did not move off the relayed head")
        self.assertEqual(self.show("feat", merge.RECORDS_PAGE), page("gap-one").strip(), "scope: the pushed page is not current")
        rc, out = self.run_merge_once("7", "--confirm", "--head", before)
        self.assertEqual(rc, 0, "under none a relayed head did not merge across the merge and page commits:\n" + out)
        self.assertEqual(self.rev("origin/main^2"), pushed, "the merge did not take the head that was pushed")
        self.assert_healed_merge(out, main_tip, before)

    def test_under_none_a_red_head_does_not_refuse_the_heal_and_merge(self):
        # Under none the tool reads no CI run at all (decision private-repos-no-ci), so a red run on the head holds no heal.
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})
        self.host.state = "red: checks: fail"  # an old run on the head, which none does not read
        rc, out = self.run_merge_once("7", "--confirm")  # one run: the case pins the single confirm, as the heal case above does
        self.assertEqual(rc, 0, "under none a red run on the head refused the heal and merge:\n" + out)
        self.assertNotIn("not green", out)

    def test_under_none_a_base_that_moves_after_the_heal_push_refuses_and_keeps_the_page_commit(self):
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})
        before = self.head()
        self.host.on_claim = lambda: self.on("main", {"debts/rival-gap.md": DEBT_TEXT.replace("Gap one", "Rival gap")}, "untooled push")
        rc, out = self.run_merge_once("7", "--confirm")
        pushed = self.head()
        self.assertNotEqual(pushed, before, "under none the stale page was not pushed, so there was no pushed commit to keep:\n" + out)
        self.assertEqual(rc, 1, out)
        self.assertFalse(getattr(self.host, "merged", False), out)
        self.assertIn("stale", out.lower())
        self.assert_page_scope(pushed, before)  # the page commit stays on the head: no revert commit sits on it

    def test_a_named_required_list_still_refuses_a_stale_page_on_a_ready_pr(self):
        # A control: under a named list the ready refusal holds, as today, before any push.
        self.set_required(["checks"])
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assert_refused_on_ready(rc, out, refs_before)

    def test_a_named_required_list_still_refuses_a_base_that_gained_a_record(self):
        # A control: under a named list a base that gained a record is refused before any push, as today. Nothing heals it.
        self.set_required(["checks"])
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})
        self.on("main", {"debts/gap-one.md": DEBT_TEXT}, "untooled push")
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assert_refused_untouched(rc, out, refs_before)
        self.assertIn("stale", out.lower())

    def test_a_named_list_refuses_a_relayed_yes_with_a_base_merge_on_top(self):
        # Under a named list no heal runs, so a merge of main on the relayed head is not the tool's own commit: the yes does not cover it.
        self.set_required(["checks"])
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})  # current for the head's own debts, so only the relayed yes can refuse the merge
        relayed = self.head()
        self.main_moves()
        main_tip = self.head("main")
        live = self.base_merge_pushed_on("origin/main")
        self.assert_merge_shape(live, relayed, main_tip, clean=True)
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertFalse(getattr(self.host, "merged", False), "a named list merged a relayed yes with a base merge on top:\n" + out)
        self.assertIn("so that yes does not cover it", out, "a named list let a relayed yes cover a base merge on top:\n" + out)
        self.assertEqual(self.refs(), refs_before, "a named list pushed on a relayed yes with a base merge on top")
        self.assertEqual(rc, 1, out)

    def test_under_none_a_merge_of_a_commit_main_never_got_refuses_the_relayed_yes(self):
        # The tree is git's clean merge, so only the second parent tells this merge apart: a base merge's second parent is on main.
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})  # current for the head's own debts, so only the relayed yes can refuse the merge
        relayed = self.head()
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "side", "origin/main")
        put_lf(os.path.join(o, "side.txt"), "a commit off main that main never got\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "side work")
        side = sh(o, "git", "rev-parse", "HEAD")
        live = self.base_merge_pushed_on("side")
        self.assert_merge_shape(live, relayed, side, clean=True)
        self.assertNotIn(side, sh(self.co, "git", "rev-list", "origin/main").split(), "fixture: the second parent is on main")
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertFalse(getattr(self.host, "merged", False), "under none a merge of a commit main never got carried a relayed yes:\n" + out)
        self.assertIn("so that yes does not cover it", out, "under none a relayed yes covered a merge whose second parent is not on main:\n" + out)
        self.assertEqual(self.refs(), refs_before, "under none a merge of a commit main never got was pushed over on a relayed yes")
        self.assertEqual(rc, 1, out)

    def test_under_none_an_edited_base_merge_refuses_the_relayed_yes(self):
        # The second parent is on main, so only the tree tells this merge apart: an edit the relayed yes did not see is not git's clean merge.
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page()})  # current for the head's own debts, so only the relayed yes can refuse the merge
        relayed = self.head()
        self.main_moves()
        main_tip = self.head("main")
        live = self.base_merge_pushed_on("origin/main", edit={"edited.txt": "a line the relayed yes never saw\n"})
        self.assert_merge_shape(live, relayed, main_tip, clean=False)
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm", "--head", relayed)
        self.assertFalse(getattr(self.host, "merged", False), "under none an edited base merge carried a relayed yes to a merge:\n" + out)
        self.assertIn("so that yes does not cover it", out, "under none a relayed yes covered an edited base merge:\n" + out)
        self.assertEqual(self.refs(), refs_before, "under none an edited base merge was pushed over on a relayed yes")
        self.assertEqual(rc, 1, out)

    def test_under_none_a_stale_page_on_a_blocked_head_refuses_before_the_heal_pushes(self):
        self.set_required("none")
        self.drop_pending_record()
        self.on("feat", {"docs/records.md": page("ghost")})  # a page that names a debt nobody has
        self.assertEqual(self.show("feat", merge.RECORDS_PAGE), page("ghost").strip(), "scope: the head's page is not the stale page")
        read = self.host.pr
        self.host.pr = lambda n: dict(read(n), merge_state="BLOCKED")  # GitHub reads the head BLOCKED, so the heal's commit would not merge
        self.assertEqual(self.host.pr(7)["merge_state"], "BLOCKED", "scope: the pull request does not read BLOCKED")
        refs_before = self.refs()
        rc, out = self.run_merge_once("7", "--confirm")
        self.assertEqual(self.refs(), refs_before, "the heal pushed onto a BLOCKED head:\n" + out)
        self.assertEqual(rc, 1, "a BLOCKED head with a stale page did not refuse:\n" + out)
        self.assertIn("reads BLOCKED", out, "the refusal does not say the head reads BLOCKED:\n" + out)
        self.assertIn(merge.HEAL_BLOCKED, out, "the refusal does not carry the heal's BLOCKED text:\n" + out)
        self.assertEqual(self.host.waits, [], "the BLOCKED refusal waited on a check")
        self.assertFalse(getattr(self.host, "merged", False), out)

    def test_a_pr_that_adds_a_debt_gets_the_page_in_the_claim_commit(self):
        self.on("feat", {"debts/gap-one.md": DEBT_TEXT})
        before = self.head()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertEqual(self.show("main", "docs/records.md"), page("gap-one").strip())
        self.assertEqual(self.claims(), 1)
        self.assertEqual(sh(self.co, "git", "rev-list", "--count", f"{before}..origin/main^2"), "1")  # one commit, claim and page together
        changed = sh(self.co, "git", "show", "--name-only", "--format=", "origin/main^2").splitlines()
        self.assertIn("docs/records.md", changed)
        self.assertIn("docs/decisions/second.md", changed)
        self.assertEqual(self.log1("%(trailers:key=Record-claim,valueonly)", "origin/main^2").strip(), "D-002")

    def test_pr_1009_ready_with_empty_stamp_kinds_refuses_a_stale_page_before_any_push(self):
        # A ready PR on a base with kinds [] and a stale page: a page-only push restarts CI after green, so confirm refuses it.
        mark = stamp_marker(self)
        self.kinds_off()
        self.on("feat", {"debts/gap-one.md": DEBT_TEXT})
        refs_before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assert_refused_on_ready(rc, out, refs_before)
        self.assertFalse(os.path.exists(mark), "stamp.mjs ran")
        self.assertEqual(self.claims(), 0, "claimed a number on a refusal")
        self.assertNotIn("docs/records.md", self.tree_names("origin/main"))

    def test_a_ready_pr_with_stamp_kinds_and_nothing_to_claim_refuses_a_stale_page(self):
        # The refusal turns on the claim, not on the config: with kinds on and no pending record, the page has no claim to ride.
        self.drop("feat", "docs/decisions/second.md", "drop the pending decision")
        self.on("feat", {"docs/records.md": page("ghost")})  # a page that names a debt nobody has
        refs_before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assert_refused_on_ready(rc, out, refs_before)

    def test_a_claim_head_on_a_base_with_no_stamp_kinds_refuses_a_stale_page_and_names_the_revert(self):
        # The base stamps nothing, so the head's Record-claim is not resumed. The draft step refuses a claim head, so the old
        # remedy (back to draft, then --confirm on the draft) loops. The path that works is to revert that claim commit first.
        self.kinds_off()
        self.claim_head({"debts/gap-one.md": DEBT_TEXT})
        refs_before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assert_refused_untouched(rc, out, refs_before)
        self.assert_revert_remedy(out)

    def test_a_resumed_claim_with_a_stale_page_still_pushes_the_page(self):
        # Pinned: a claim the head already holds is resumed, and its stale page rides one commit on top of it, as before the ruling.
        self.claim_head({"debts/gap-one.md": DEBT_TEXT})
        before = self.head()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertIn("already holds the claim D-002", out)
        after = self.rev("origin/main^2")  # the head's own commit, merged: feat is deleted after the merge
        self.assertNotEqual(after, before)
        self.assertEqual(sh(self.co, "git", "rev-list", "--count", f"{before}..{after}"), "1")
        self.assertEqual(self.log1("%s", after), "Rebuild the records page")
        self.assertEqual(self.log1("%(trailers:key=Record-claim,valueonly)", after).strip(), "")
        self.assertIn(merge.RECORDS_PAGE, self.log1("%(trailers:key=Drops-lines,valueonly)", after))
        self.assertEqual(self.show("main", merge.RECORDS_PAGE), page("gap-one").strip())
        self.assertEqual(self.host.waits, [], "confirm waited on a check")  # no wait: the head was read green, and nothing waits on the page commit
        self.assertTrue(getattr(self.host, "merged", False), out)

