MAIN_WORKFLOW = "\n".join([
    "name: checks", "on: push", "jobs:",
    "  checks:", "    runs-on: ubuntu-latest", "    timeout-minutes: 50", "    steps:", "      - run: echo ok",
    "  scope:", "    runs-on: ubuntu-latest", "    timeout-minutes: 10", "    steps:", "      - run: echo ok",
    "  checks-macos:", "    runs-on: macos-latest", "    timeout-minutes: 30", "    steps:", "      - run: echo ok",
]) + "\n"


LINKS_PATH = ".github/workflows/links.yml"  # one job, run on a schedule and by dispatch: the two event groups of one file
LINKS_WORKFLOW = "\n".join([
    "name: links", "on:", "  schedule:", "    - cron: \"0 6 * * *\"", "  workflow_dispatch:", "jobs:",
    "  readme-links:", "    runs-on: ubuntu-latest", "    timeout-minutes: 15", "    steps:", "      - run: echo ok",
]) + "\n"


def main_run(id_, conclusion, status="completed", name="checks", event="push", path=".github/workflows/checks.yml", sha=None, run_attempt=1, message=None):
    """One run on main, as `GET actions/runs` lists it. Its head is `sha`, or a sha of its own id. A re-run keeps its id, at `run_attempt` 2 or more.
    `message` is the head commit's message, as GitHub gives it in `head_commit` and `display_title`: a merge commit names its pull request in it."""
    run = {"id": id_, "name": name, "path": path, "event": event, "status": status, "conclusion": conclusion if status == "completed" else None,
           "head_sha": sha or f"{id_:040x}", "html_url": f"https://github.com/o/r/actions/runs/{id_}", "run_attempt": run_attempt}
    if message is not None:
        run["display_title"], run["head_commit"] = message.splitlines()[0], {"message": message}
    return run


def main_job(name, conclusion, minutes=1):
    """One completed job of a main run, as `GET actions/runs/<id>/jobs` lists it: it ran from START for `minutes`."""
    return {"name": name, "status": "completed", "conclusion": conclusion, "started_at": at(0), "completed_at": at(minutes),
            "html_url": f"https://github.com/o/r/actions/runs/1/job/{len(name)}"}


# The workflow file a head serves when a case gives none: one job with no if:, so every job name reads as one that may run.
NO_IF_WORKFLOW = "\n".join(["name: checks", "on: push", "jobs:", "  checks:", "    runs-on: ubuntu-latest", "    steps:", "      - run: echo ok"]) + "\n"
CHECKS_PATH = ".github/workflows/checks.yml"
REAL_CHECKS = os.path.join(os.path.dirname(HERE), ".github", "workflows", "checks.yml")  # the file as it is on disk, never a stub
# The live nightly case: schedule run LIVE_R failed on checks-windows-merge-3, all-jobs-passed and ci-done skipped; the newer push run LIVE_N
# passed merge-3 and skipped the same two. Their jobs and conclusions are the ones test_action.sh's live case gives too.
LIVE_R, LIVE_N = 41817705653, 41905916525
LIVE_N_SHA = f"{LIVE_N:040x}"


def real_checks():
    with open(REAL_CHECKS, encoding="utf-8") as f:
        return f.read()


def live_nightly():
    """-> (main_runs, jobs) of the live nightly case, newest run first, as GET actions/runs and the jobs read give them."""
    runs = [main_run(LIVE_N, "success", sha=LIVE_N_SHA, path=CHECKS_PATH), main_run(LIVE_R, "failure", event="schedule", path=CHECKS_PATH)]
    jobs = {LIVE_R: [main_job("checks-windows-merge-3", "failure", 19), main_job("all-jobs-passed", "skipped"), main_job("ci-done", "skipped")],
            LIVE_N: [main_job("checks-windows-merge-3", "success", 19), main_job("all-jobs-passed", "skipped"), main_job("ci-done", "skipped")]}
    return runs, jobs


class MainRunsHost(FakeHost, merge.Host):
    """FakeHost for the flow; the real Host.base_state over scripted REST. `main_runs`: main's push runs, newest first. `jobs`: run id -> jobs.
    `runs_fail` / `jobs_fail`: that read fails with this text. `jobs_fail_of`: run id -> the text its jobs read fails with.
    `texts`: head sha -> the workflow file's text on that head (a head not in it reads as NO_IF_WORKFLOW). `text_fail`: every file read fails with this text.
    `pulls`: {number: REST row} of the pull requests the page holds (None: the own one only). `heads`: head sha -> the checks state head_state reads for it.
    `changed`: the (path, status, additions) triples of the own pull request's diff (pr_files reads them); None keeps FakeHost's README.md.
    `named_checks`: the (name, state, head) rows check_state reads. `job_logs`: job id -> the text `actions/jobs/N/logs` returns; a job with none is a 404. `required`: the merge.requiredChecks the real Host holds, "protection" by default."""
    base_state = getattr(merge.Host, "base_state", None)

    def __init__(self, root, other, main_runs, jobs, runs_fail=None, jobs_fail=None, jobs_fail_of=None, texts=None, text_fail=None, pulls=None, heads=None, changed=None,
                 named_checks=None, job_logs=None, required="protection"):
        FakeHost.__init__(self, root, other)
        self.required = required  # base_state branches on it; "protection" is what the real Host gets for a protected main (merge.MERGE_DEFAULTS)
        self.ignore, self.cwd, self.warned = {}, root, set()
        self.main_runs, self.jobs, self.runs_fail, self.jobs_fail, self.reads = main_runs, jobs, runs_fail, jobs_fail, []
        self.jobs_fail_of = jobs_fail_of or {}
        self.texts, self.text_fail = texts or {}, text_fail
        self.pulls, self.head_states = pulls, heads or {}
        if changed is not None:
            self.changed = list(changed)
        self.named_checks, self.job_logs = list(named_checks or []), dict(job_logs or {})

    def file_at_head(self, rel, extra, fields):
        """`contents/<path>` read at a head: the ref is a field or a query. Raw when the Accept header asks for raw, else the JSON reply with base64 content."""
        query = re.search(r"[?&]ref=([0-9a-f]+)", rel)
        ref = fields.get("ref") or (query and query.group(1))
        if self.text_fail:
            return 1, self.text_fail
        text = self.texts.get(ref, NO_IF_WORKFLOW)
        if any("vnd.github.raw" in a for a in extra):
            return 0, text
        return 0, json.dumps({"encoding": "base64", "content": base64.b64encode(text.encode("utf-8")).decode("ascii")})

    def api(self, rel, *extra, method="GET", fields=None):
        self.reads.append(rel)
        if rel.startswith("contents/"):
            return self.file_at_head(rel, extra, fields or {})
        m = re.fullmatch(r"actions/jobs/(\d+)/logs", rel)
        if m:  # a job's log text; a job with no log scripted is a 404, which the reader takes as unknown
            return (0, self.job_logs[int(m.group(1))]) if int(m.group(1)) in self.job_logs else (1, "HTTP 404: Not Found")
        assert (rel, method, fields.get("branch")) == ("actions/runs", "GET", "main"), (rel, fields)
        if self.runs_fail:
            return 1, self.runs_fail
        runs = [r for r in self.main_runs if fields.get("event") in (None, r["event"])]  # GitHub's event filter, when one is sent
        return 0, json.dumps({"total_count": len(runs), "workflow_runs": runs})

    def pages(self, rel, key=None, fields=None):
        self.reads.append(rel)
        m = re.fullmatch(r"actions/runs/(\d+)/jobs", rel)
        assert m and key == "jobs", rel
        fail = self.jobs_fail_of.get(int(m.group(1)), self.jobs_fail)
        if fail:
            raise merge.Stop(f"reading {rel} from GitHub failed: {fail}")
        return self.jobs[int(m.group(1))]

    def head_state(self, n, sha=None):
        """The checks state a case scripts for a head (`heads`), else the FakeHost default. A case with `pulls` has no other pull request: a number
        not on that page is no pull request, so its checks read unknown."""
        if sha in self.head_states:
            return self.head_states[sha]
        if self.pulls is not None and n != self.own_number and n not in self.pulls:
            return f"unknown (pull request #{n} is not on the page)"
        return FakeHost.head_state(self, n, sha)


class RedMainBrake(Env):
    """c166: no batch merge onto a red main. The red-main check judges main's latest completed run, job by job (decision no-merge-onto-red-main)."""
    def setUp(self):
        super().setUp()
        self.base_on_main()

    def base_on_main(self):
        """Main gets the files the timeout verdict and the judged paths read."""
        push_base(self, {".github/workflows/checks.yml": MAIN_WORKFLOW, LINKS_PATH: LINKS_WORKFLOW})

    def fresh_repos(self):
        """A new origin and clones with the same base on main. A merge deletes its feat, so each later merge in one case starts here."""
        self.new_repos()
        self.base_on_main()

    def go(self, runs, jobs, *flags, confirm=True, **kw):
        self.host = MainRunsHost(self.co, self.other, runs, jobs, **kw)
        before = self.refs()
        rc, out = self.run_merge("7", *(["--confirm"] if confirm else []), *flags)
        return rc, out, before

    def refused(self, rc, out, before):
        self.assertEqual(rc, 1, out)
        self.assertFalse(getattr(self.host, "merged", False), out)
        self.assertEqual(self.refs(), before, "a refused run claims and pushes nothing")
        self.assertFalse(self.lock_ref(), "the lock is freed")

    def merged(self, rc, out):
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), out)

    # Ruling Q5 v (owner, chat, 10:42 CST Nov 20, 2026): a PR may merge onto a red main, and the merge tool prints main's red checks and their
    # failing tests on each merge. The helpers below replace the refusal this class used to assert for a red verdict.
    def merged_onto_red(self, rc, out, *names):
        """A PR merges onto a red main (ruling Q5 v). One printed line names every one of `names`, when given."""
        self.assertEqual(rc, 0, "a PR was refused on a red main, and ruling Q5 v lets it merge:\n" + out)
        self.assertTrue(getattr(self.host, "merged", False), "the merge call was not sent:\n" + out)
        self.assertNotIn("No batch merges onto a red main", out, "the red main still refuses the merge")
        if names:
            self.assertTrue(any(all(n in line for n in names) for line in out.splitlines()),
                            f"no one printed line names {', '.join(names)}:\n{out}")

    def refused_by_head(self, rc, out, before):
        """A PR whose own checks are not green is refused by its head, never by the red main (ruling Q5 v)."""
        RedMainBrake.refused(self, rc, out, before)
        self.assertNotIn("No batch merges onto a red main", out, "the red main refused a PR whose own head is not green")

    def red_detail(self):
        """The detail of main's red verdict, as base_verdict reads it on this case's host: the blamed run, its pull request, and the walk's stops."""
        verdict, detail = merge.base_verdict(self.co, self.host, "main")
        self.assertEqual(verdict, "red", detail)
        return detail

