        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-q", "-m", "main adds the same file"); sh(o, "git", "push", "-q", "origin", "main")
        sh(self.co, "git", "fetch", "-q", "origin")
        _, lines, err, _ = self.release([7])
