GUARD_MAIN = "def check(ctx):\n    return None\n"
GUARD_FEAT = GUARD_MAIN + 'def widget(ctx):\n    return refuse(ctx, "a widget was made", "widget-slug-rule")\n'
MANY_RECORDS = 75  # decision records one PR lands, for the cap case
